INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(287470, 20434, 6202, '<td valign="top">Very vibrant colors and great focus, very nicely done.</td>', 'Very vibrant colors and great focus, very nicely done.', '2003-05-05 01:03:28.000000', NULL, 1),
(287483, 20516, 6202, '<td valign="top">Wonderful photo, of the Opryhouse.  The angle you captured this at keeps it from appearing to be a falling building.  well worth a 10.</td>', 'Wonderful photo, of the Opryhouse.  The angle you captured this at keeps it from appearing to be a falling building.  well worth a 10.', '2003-05-05 01:09:46.000000', NULL, 1),
(287486, 20504, 4267, '<td valign="top">home sweet home! :o) well at least it next door to sweet ft worth :o) that your shot seeker?  the old courthouse looks nicely exposed.... good color... but the sky is washed... always tough to work with... nice compostition though</td>', 'home sweet home! :o) well at least it next door to sweet ft worth :o) that your shot seeker?  the old courthouse looks nicely exposed.... good color... but the sky is washed... always tough to work with... nice compostition though', '2003-05-05 01:11:53.000000', NULL, 1),
(287488, 20535, 806, '<td valign="top">lots of noise in this photograph, but I like the composition and the colors.</td>', 'lots of noise in this photograph, but I like the composition and the colors.', '2003-05-05 01:12:00.000000', NULL, 1),
(287490, 20335, 806, '<td valign="top">Oh how I loved the Olympic Penninsula! This makes me want to go there again! Someday I will. In the meantime thanks for the postcard! :P<br/>I love the colors of the sunset, and the silouette of the arch and how it is repeated in the branch.</td>', 'Oh how I loved the Olympic Penninsula! This makes me want to go there again! Someday I will. In the meantime thanks for the postcard! :PI love the colors of the sunset, and the silouette of the arch and how it is repeated in the branch.', '2003-05-05 01:13:12.000000', NULL, 1),
(287492, 20267, 6870, '<td valign="top">Lots of cool drama in the sky contrast with the different white of the mountains. Nice work, babe!</td>', 'Lots of cool drama in the sky contrast with the different white of the mountains. Nice work, babe!', '2003-05-05 01:14:26.000000', NULL, 1),
(287493, 20501, 7706, '<td valign="top">Thats so pretty. love the colors, and texture of the water :) I like the way you did your text too, on the side. Different to everyone elses :)</td>', 'Thats so pretty. love the colors, and texture of the water :) I like the way you did your text too, on the side. Different to everyone elses :)', '2003-05-05 01:14:59.000000', NULL, 1),
(287495, 20432, 806, '<td valign="top">gorgeous! nice work!</td>', 'gorgeous! nice work!', '2003-05-05 01:15:43.000000', NULL, 1),
(287498, 20332, 4625, '<td valign="top">The resolution seems like it could have been higher (might just be a higher ISO Causing a grainy feeling in low light). I like the concept of this picture though.</td>', 'The resolution seems like it could have been higher (might just be a higher ISO Causing a grainy feeling in low light). I like the concept of this picture though.', '2003-05-05 01:16:04.000000', NULL, 1),
(287500, 20507, 4625, '<td valign="top">I like the use of Depth of field, but it would have been more powerful with baseball cleats in the pic instead of normal running shoes. And maybe also putting a team name on the picture to give it more of a postcard feel would have helped.</td>', 'I like the use of Depth of field, but it would have been more powerful with baseball cleats in the pic instead of normal running shoes. And maybe also putting a team name on the picture to give it more of a postcard feel would have helped.', '2003-05-05 01:17:45.000000', NULL, 1),
(287503, 20439, 806, '<td valign="top">exceptional.</td>', 'exceptional.', '2003-05-05 01:18:57.000000', NULL, 1),
(287504, 20342, 4625, '<td valign="top">Interesting angle for this shot. It seems a little too dark to me, even being in the shadows of the trees. It doesn\''t have too much of a postcard feel to it either. a frame and text might have helped.</td>', 'Interesting angle for this shot. It seems a little too dark to me, even being in the shadows of the trees. It doesn\''t have too much of a postcard feel to it either. a frame and text might have helped.', '2003-05-05 01:19:01.000000', NULL, 1),
(287506, 20210, 806, '<td valign="top">I like this alot, I wish the words were not covering the flowers.. perhaps arranging them in a different way would help.. but overall nice postcard.</td>', 'I like this alot, I wish the words were not covering the flowers.. perhaps arranging them in a different way would help.. but overall nice postcard.', '2003-05-05 01:19:47.000000', NULL, 1),
(287508, 20331, 4625, '<td valign="top">THis doesn''t have a postcard feel it to for me. The picture itself could have been great, but it seems the higher iso, or long exposure caused a bit of grain which distracts me from teh beauty of the sun through the tree. a border might have helped this feel like a postcard more.</td>', 'THis doesn''t have a postcard feel it to for me. The picture itself could have been great, but it seems the higher iso, or long exposure caused a bit of grain which distracts me from teh beauty of the sun through the tree. a border might have helped this feel like a postcard more.', '2003-05-05 01:21:12.000000', NULL, 1),
(287509, 20280, 4625, '<td valign="top">Beautiful picture. The sky looks a slight bit over exposed compared ot the ground. but not too bad. I like the border on this, adn the text is very suiting. Well done.</td>', 'Beautiful picture. The sky looks a slight bit over exposed compared ot the ground. but not too bad. I like the border on this, adn the text is very suiting. Well done.', '2003-05-05 01:22:15.000000', NULL, 1),
(287510, 20518, 4625, '<td valign="top">Great concept. Executed well too. Panning is definitely tough to get perfect. It''d have been nice if the taxi was a little bit clearer. Also I think a motion effect on the text would look great (though I''m not sure if that would have been legal). Nice shot</td>', 'Great concept. Executed well too. Panning is definitely tough to get perfect. It''d have been nice if the taxi was a little bit clearer. Also I think a motion effect on the text would look great (though I''m not sure if that would have been legal). Nice shot', '2003-05-05 01:23:46.000000', NULL, 1),
(287514, 20428, 806, '<td valign="top">I like this alot. I wonder what it would look like in color. I imagine it would look great! Would love to see the colors of the area.</td>', 'I like this alot. I wonder what it would look like in color. I imagine it would look great! Would love to see the colors of the area.', '2003-05-05 01:25:16.000000', NULL, 1),
(287515, 20405, 6870, '<td valign="top">Menschmeier! I wish I was back in good ol'' Germany! Nice postcard--makes we want to go there! Wonderful composition, focus and colors. Clear and engaging!</td>', 'Menschmeier! I wish I was back in good ol'' Germany! Nice postcard--makes we want to go there! Wonderful composition, focus and colors. Clear and engaging!', '2003-05-05 01:25:42.000000', NULL, 1),
(287518, 20462, 4625, '<td valign="top">I really like this picture and I think the text color is perfect with the black border, overall just love it. Well done.</td>', 'I really like this picture and I think the text color is perfect with the black border, overall just love it. Well done.', '2003-05-05 01:27:27.000000', NULL, 1),
(287519, 20439, 4625, '<td valign="top">This looks just like a postcard. Very well done, great image, nice framing, and the text is done well.</td>', 'This looks just like a postcard. Very well done, great image, nice framing, and the text is done well.', '2003-05-05 01:27:58.000000', NULL, 1),
(287520, 20298, 4625, '<td valign="top">Beautiful picture! The border is fabulous, this looks just like a postcard. The text is very fitting too. excellent job.</td>', 'Beautiful picture! The border is fabulous, this looks just like a postcard. The text is very fitting too. excellent job.', '2003-05-05 01:28:40.000000', NULL, 1),
(287521, 20268, 6870, '<td valign="top">The font Comic Sans is very passe, and I''d advise you not to use it anymore. But barring that, this is a GREAT pic of my former home town (Irvine)! Great composition, colors, and a refreshingly original idea.</td>', 'The font Comic Sans is very passe, and I''d advise you not to use it anymore. But barring that, this is a GREAT pic of my former home town (Irvine)! Great composition, colors, and a refreshingly original idea.', '2003-05-05 01:28:58.000000', NULL, 1),
(287523, 20497, 4625, '<td valign="top">I like the curves in this picture it looks great. I Also like the border used, and I love the text on teh bottom of the picture. The different font for the top text seems a bit awkward to me but it doesn''t take away from the picture much. Overall well done.</td>', 'I like the curves in this picture it looks great. I Also like the border used, and I love the text on teh bottom of the picture. The different font for the top text seems a bit awkward to me but it doesn''t take away from the picture much. Overall well done.', '2003-05-05 01:29:46.000000', NULL, 1),
(287524, 20514, 806, '<td valign="top">i like how you can see the horizon/mountains.. nice!</td>', 'i like how you can see the horizon/mountains.. nice!', '2003-05-05 01:31:14.000000', NULL, 1),
(287525, 20432, 4625, '<td valign="top">This picture is fabulous! Looks great! The border is perfect as is the text, very fitting. Overall well done! This is fabulous and a pleasure to look at.</td>', 'This picture is fabulous! Looks great! The border is perfect as is the text, very fitting. Overall well done! This is fabulous and a pleasure to look at.', '2003-05-05 01:31:21.000000', NULL, 1),
(287527, 20370, 4625, '<td valign="top">Great image! I love the twilight shot, the colors are so vibrant, and hte lighting is awesome. The only thing I don''t care for is the text. It doesn''t seem to fit so well. However it''s not distracting enough to take away points. Well done!</td>', 'Great image! I love the twilight shot, the colors are so vibrant, and hte lighting is awesome. The only thing I don''t care for is the text. It doesn''t seem to fit so well. However it''s not distracting enough to take away points. Well done!', '2003-05-05 01:32:13.000000', NULL, 1),
(287530, 20405, 4625, '<td valign="top">Excellent shot I liek the angle a great deal. The border is very fitting, and the text goes along perfectly. Looks just like a postcard. Well done!</td>', 'Excellent shot I liek the angle a great deal. The border is very fitting, and the text goes along perfectly. Looks just like a postcard. Well done!', '2003-05-05 01:32:53.000000', NULL, 1),
(287532, 20482, 3669, '<td valign="top">This was an amazing idea!!  True spirit of Texas and nice photographic art.  I would have definately bought this as a post card if visiting to send.  Now I can''t wait to find out what statue this came from and where.  I haven''t been through very many entries yet, but I truely believe that you have a winner.  10</td>', 'This was an amazing idea!!  True spirit of Texas and nice photographic art.  I would have definately bought this as a post card if visiting to send.  Now I can''t wait to find out what statue this came from and where.  I haven''t been through very many entries yet, but I truely believe that you have a winner.  10', '2003-05-05 01:34:01.000000', NULL, 1),
(287535, 20334, 4625, '<td valign="top">I''m not sure how you achieved this effect without an image altering filter, but this looks fabulous. Looks just like a post card, The colors are awesome together. well done.</td>', 'I''m not sure how you achieved this effect without an image altering filter, but this looks fabulous. Looks just like a post card, The colors are awesome together. well done.', '2003-05-05 01:35:03.000000', NULL, 1),
(287536, 20439, 6870, '<td valign="top">Oh boy, I''m glad  you didn''t take a picture of sick people! This one is much better! I love how the tower rises dramatically. Very balanced photo, too.</td>', 'Oh boy, I''m glad  you didn''t take a picture of sick people! This one is much better! I love how the tower rises dramatically. Very balanced photo, too.', '2003-05-05 01:35:25.000000', NULL, 1),
(287540, 20270, 4625, '<td valign="top">I lke the framing on this picture a great deal. I''m saddened that it''s not The full 640 pixels in height. I think it would bring out more detail in the pegasus (The focal point of the picture) if it was larger.</td>', 'I lke the framing on this picture a great deal. I''m saddened that it''s not The full 640 pixels in height. I think it would bring out more detail in the pegasus (The focal point of the picture) if it was larger.', '2003-05-05 01:36:54.000000', NULL, 1),
(287543, 20269, 4625, '<td valign="top">On a cloudier day I''d say that text would be very fitting, however with a nearly perfect blue sky that text seems very out of place in this picture. A gradient with more blue in it might have looked better... The image itself looks great. The only bad thing about it si the sahdows on some of the buildings, a different time of day might have corrected this. Overall I''d have to say well done. it loooks good.</td>', 'On a cloudier day I''d say that text would be very fitting, however with a nearly perfect blue sky that text seems very out of place in this picture. A gradient with more blue in it might have looked better... The image itself looks great. The only bad thing about it si the sahdows on some of the buildings, a different time of day might have corrected this. Overall I''d have to say well done. it loooks good.', '2003-05-05 01:39:22.000000', NULL, 1),
(287544, 20268, 3669, '<td valign="top">I really like the composition of your photo for your postcard.  The lighting and color is nice.  I feel like I could actually smell the oranges.  The text is well placed and very fitting.  The bright blue border really hurts it, though.</td>', 'I really like the composition of your photo for your postcard.  The lighting and color is nice.  I feel like I could actually smell the oranges.  The text is well placed and very fitting.  The bright blue border really hurts it, though.', '2003-05-05 01:40:04.000000', NULL, 1),
(287546, 19947, 4625, '<td valign="top">This is a beautiful picture of simplicity. I love it. the colors are fabulous, the border is very fitting, as is the text. Overall well done.</td>', 'This is a beautiful picture of simplicity. I love it. the colors are fabulous, the border is very fitting, as is the text. Overall well done.', '2003-05-05 01:40:10.000000', NULL, 1),
(287548, 20399, 5007, '<td valign="top">Whoa! Another Bellinghamite! And I drove to Hansville to take a picture! Thought about the mural on State St.  Nice job :-)</td>', 'Whoa! Another Bellinghamite! And I drove to Hansville to take a picture! Thought about the mural on State St.  Nice job :-)', '2003-05-05 01:40:34.000000', NULL, 1),
(287551, 20456, 4625, '<td valign="top">Weondeful use of symetry. This picture looks great! Flag waving and all. The only thing I might change is the choice in text. something simpler might have looked better. none the less, overall this is a wonderful image.</td>', 'Weondeful use of symetry. This picture looks great! Flag waving and all. The only thing I might change is the choice in text. something simpler might have looked better. none the less, overall this is a wonderful image.', '2003-05-05 01:42:51.000000', NULL, 1),
(287554, 20399, 4625, '<td valign="top">Beautiful image. The centering of the tree in the shot worked really well. The text is very fitting doens''t take away from the image at all. Well done.</td>', 'Beautiful image. The centering of the tree in the shot worked really well. The text is very fitting doens''t take away from the image at all. Well done.', '2003-05-05 01:44:13.000000', NULL, 1),
(287555, 19993, 6202, '<td valign="top">Interesting photo, color is fantastic and the focus is very sharp.</td>', 'Interesting photo, color is fantastic and the focus is very sharp.', '2003-05-05 01:44:16.000000', NULL, 1),
(287558, 20154, 4625, '<td valign="top">A breath taking sunset. The border and text fit wonderfully. This could very easily be a postcard. Well done!</td>', 'A breath taking sunset. The border and text fit wonderfully. This could very easily be a postcard. Well done!', '2003-05-05 01:44:46.000000', NULL, 1),
(287560, 20268, 4625, '<td valign="top">I don''t care for the blue border on this one. A green border, or an orange border, or a white border or something might have worked a lot better. The blue border is very distracting from teh nicely done picture.</td>', 'I don''t care for the blue border on this one. A green border, or an orange border, or a white border or something might have worked a lot better. The blue border is very distracting from teh nicely done picture.', '2003-05-05 01:45:32.000000', NULL, 1),
(287561, 20523, 6202, '<td valign="top">Nice image, just wondering if the outline is a structure, filter or a mask.</td>', 'Nice image, just wondering if the outline is a structure, filter or a mask.', '2003-05-05 01:45:46.000000', NULL, 1),
(287562, 20525, 4625, '<td valign="top">The text seems a littel grainy. Not sure what happened there. With that said, the picture itself looks great. Teh colors are really smooth and feel really good in this image. It''s a great shot and very fitting as a postcard.</td>', 'The text seems a littel grainy. Not sure what happened there. With that said, the picture itself looks great. Teh colors are really smooth and feel really good in this image. It''s a great shot and very fitting as a postcard.', '2003-05-05 01:46:21.000000', NULL, 1),
(287563, 20525, 3669, '<td valign="top">Hey!!  I used to live in Cisco, TX!  I''m really enjoying this challenge and being able to re-visit places.  Sorry...onto more important things.  :-)  The placement of these longhorns is absolutely perfect!!  You had to have trained them to pose, however, it would have helped if the beautiful one in front had his eyes open.  The lighting is perfect, the colors came out great and there is good focus and definition.  True spirit of Texas!  10</td>', 'Hey!!  I used to live in Cisco, TX!  I''m really enjoying this challenge and being able to re-visit places.  Sorry...onto more important things.  :-)  The placement of these longhorns is absolutely perfect!!  You had to have trained them to pose, however, it would have helped if the beautiful one in front had his eyes open.  The lighting is perfect, the colors came out great and there is good focus and definition.  True spirit of Texas!  10', '2003-05-05 01:46:35.000000', NULL, 1),
(287564, 20269, 6202, '<td valign="top">WOW what a fantastic photo, I thought I had already seen some great postcards but this one is incredible.  Very well done.   Well worth a 10.</td>', 'WOW what a fantastic photo, I thought I had already seen some great postcards but this one is incredible.  Very well done.   Well worth a 10.', '2003-05-05 01:47:40.000000', NULL, 1),
(287566, 20078, 4625, '<td valign="top">I think this border would hav ebeen better without a drop shadow. It seems to give it a funny feel. Aside from that the image itself is pretty good though it seems somewhat small. It''s hard ot make out some of the details taht owuld add a lot to this image. The color of hte text seems slightly out of place too. Overall nice shot.</td>', 'I think this border would hav ebeen better without a drop shadow. It seems to give it a funny feel. Aside from that the image itself is pretty good though it seems somewhat small. It''s hard ot make out some of the details taht owuld add a lot to this image. The color of hte text seems slightly out of place too. Overall nice shot.', '2003-05-05 01:50:31.000000', NULL, 1),
(287567, 20154, 6202, '<td valign="top">Very nice sunset, the colors set a mood for the entire image.</td>', 'Very nice sunset, the colors set a mood for the entire image.', '2003-05-05 01:50:39.000000', NULL, 1),
(287570, 20161, 4625, '<td valign="top">The orange text feels out of place here for me. With that aside the photo itself looks really good I like it a lot. The colors are great, and the scene is very beautiful.</td>', 'The orange text feels out of place here for me. With that aside the photo itself looks really good I like it a lot. The colors are great, and the scene is very beautiful.', '2003-05-05 01:51:36.000000', NULL, 1),
(287571, 20396, 4625, '<td valign="top">Beautiful image! This would make a great postcard shot. The sky color is very smooth I like that, and the focus looks pretty crisp all throughout. well done.</td>', 'Beautiful image! This would make a great postcard shot. The sky color is very smooth I like that, and the focus looks pretty crisp all throughout. well done.', '2003-05-05 01:53:02.000000', NULL, 1),
(287572, 20434, 4625, '<td valign="top">The focus looks a little off here to me. I love hte angle of this shot and the overall view I''m being shown though. it looks fabulous. A great postcard no doubt. The text on this one is also very fitting. Well done.</td>', 'The focus looks a little off here to me. I love hte angle of this shot and the overall view I''m being shown though. it looks fabulous. A great postcard no doubt. The text on this one is also very fitting. Well done.', '2003-05-05 01:53:50.000000', NULL, 1),
(287573, 20482, 4625, '<td valign="top">I like the use of the tweaked text here. It''s very fitting to this image. Overall well done. would make a great postcard.</td>', 'I like the use of the tweaked text here. It''s very fitting to this image. Overall well done. would make a great postcard.', '2003-05-05 01:54:19.000000', NULL, 1),
(287574, 20280, 6202, '<td valign="top">The mountains and sky are very eye catching sadly though the structure seems to be lost in darlness after all the light at the top of the photo.  Also the font you chose seems to be too fine and just kind of blends in with the border.  Your focus however is great everything seems to be in very sharp focus.  This one is hard to score cause it has both its good and bad points.</td>', 'The mountains and sky are very eye catching sadly though the structure seems to be lost in darlness after all the light at the top of the photo.  Also the font you chose seems to be too fine and just kind of blends in with the border.  Your focus however is great everything seems to be in very sharp focus.  This one is hard to score cause it has both its good and bad points.', '2003-05-05 01:54:55.000000', NULL, 1),
(287575, 20446, 4625, '<td valign="top">The horse looks a little too red here to me. Also the branch lying in the grass looks like it oculd be a picture flaw more than just a branch. It might have been better ot move that branch. The text and the border are both very fitting, very postcard like. Overall this image is really good, with very minor nit picky details I''d change. Well done.</td>', 'The horse looks a little too red here to me. Also the branch lying in the grass looks like it oculd be a picture flaw more than just a branch. It might have been better ot move that branch. The text and the border are both very fitting, very postcard like. Overall this image is really good, with very minor nit picky details I''d change. Well done.', '2003-05-05 01:55:30.000000', NULL, 1),
(287576, 20439, 6202, '<td valign="top">Well done, captured on a very pretty day too.</td>', 'Well done, captured on a very pretty day too.', '2003-05-05 01:56:35.000000', NULL, 1),
(287577, 20356, 4625, '<td valign="top">Beautiful picture. Looks great! This would make a very good post card, fits the challenge wonderfully. The focus on teh flowers seems a little too soft, but other than that it''s superb.</td>', 'Beautiful picture. Looks great! This would make a very good post card, fits the challenge wonderfully. The focus on teh flowers seems a little too soft, but other than that it''s superb.', '2003-05-05 01:56:49.000000', NULL, 1),
(287579, 20340, 4625, '<td valign="top">I like the dimmensions of this one. Very nice. I Also like the border being only on the bottom as it is. The text is very fitting and this would make a great postcard. It seems slightly overexposed or brightened a small bit too much but other than that it''s a great image.</td>', 'I like the dimmensions of this one. Very nice. I Also like the border being only on the bottom as it is. The text is very fitting and this would make a great postcard. It seems slightly overexposed or brightened a small bit too much but other than that it''s a great image.', '2003-05-05 01:57:40.000000', NULL, 1),
(287580, 20411, 4625, '<td valign="top">the text feels fairly out of place in this one. a different color might have worked better, or maybe just a lighter border to offset it a bit. The image itself looks fabulout though the green looks a tad bit too bright. Overall this fits the challenge wonderful. Good job.</td>', 'the text feels fairly out of place in this one. a different color might have worked better, or maybe just a lighter border to offset it a bit. The image itself looks fabulout though the green looks a tad bit too bright. Overall this fits the challenge wonderful. Good job.', '2003-05-05 01:58:53.000000', NULL, 1),
(287581, 20442, 6202, '<td valign="top">Aaahhhhh the shoreline, very nice capture of the gentle waves coming in.  Almost can see some friend sending me this knowing how much I love to watch the waves as they come in, with a note wrote to me saying, Don''t you wish you were here too.  Makes me want to go to the beach.</td>', 'Aaahhhhh the shoreline, very nice capture of the gentle waves coming in.  Almost can see some friend sending me this knowing how much I love to watch the waves as they come in, with a note wrote to me saying, Don''t you wish you were here too.  Makes me want to go to the beach.', '2003-05-05 01:59:53.000000', NULL, 1),
(287582, 20481, 4625, '<td valign="top">THe contrast on this picture seems a bit to high to me. The Greens are so green, yet somehow the blues aren''t very blue. The shot itself is really nice I like the perspective here a great deal. The white text doesn''t seem to fit very well, I''m not sure what I would do to make that look better. Overall this would be a decent postcard. Good job.</td>', 'THe contrast on this picture seems a bit to high to me. The Greens are so green, yet somehow the blues aren''t very blue. The shot itself is really nice I like the perspective here a great deal. The white text doesn''t seem to fit very well, I''m not sure what I would do to make that look better. Overall this would be a decent postcard. Good job.', '2003-05-05 02:00:09.000000', NULL, 1),
(287583, 20317, 4625, '<td valign="top">The reds seem to be very oersaturated here. The image is nice in perspective, but the colors and details seem off. The border is nice nad this shot could make a good postcard, but the color is too saturated.</td>', 'The reds seem to be very oersaturated here. The image is nice in perspective, but the colors and details seem off. The border is nice nad this shot could make a good postcard, but the color is too saturated.', '2003-05-05 02:01:40.000000', NULL, 1),
(287585, 20138, 4625, '<td valign="top">The text on this might have looked better in either the top left or top right corner instead of dead center. The image is nice, but not too many details can be made out. it does have that postcard feel to it though. The blue border seems slightly out of place a white one might have been better. Overall not bad.</td>', 'The text on this might have looked better in either the top left or top right corner instead of dead center. The image is nice, but not too many details can be made out. it does have that postcard feel to it though. The blue border seems slightly out of place a white one might have been better. Overall not bad.', '2003-05-05 02:02:46.000000', NULL, 1),
