(287794, 20269, 7800, '<td valign="top">Great font, love the blue skies, and the vantage point you chose is awesome; great shapes!</td>', 'Great font, love the blue skies, and the vantage point you chose is awesome; great shapes!', '2003-05-05 10:32:58.000000', NULL, 1),
