(288468, 20444, 6532, '<td valign="top">Wall in the front is a bit too much.  Nice overall</td>', 'Wall in the front is a bit too much.  Nice overall', '2003-05-05 21:01:38.000000', NULL, 1),
(288473, 20497, 6532, '<td valign="top">Too much wall on the left....  The different fonts do not compliment.  I like the bottom font - works well with the overall mood of the picture</td>', 'Too much wall on the left....  The different fonts do not compliment.  I like the bottom font - works well with the overall mood of the picture', '2003-05-05 21:02:59.000000', NULL, 1),
