(288491, 19947, 6532, '<td valign="top">Nice</td>', 'Nice', '2003-05-05 21:14:34.000000', NULL, 1),
(288492, 20240, 806, '<td valign="top">this is a nice shot, but a bit slanted. love the seagull perched onto the boat, and the lighthouse in the background. the grainy/noisy artifacts can be cleaned up a bit too. nice colors.</td>', 'this is a nice shot, but a bit slanted. love the seagull perched onto the boat, and the lighthouse in the background. the grainy/noisy artifacts can be cleaned up a bit too. nice colors.', '2003-05-05 21:14:36.000000', NULL, 1),
