(289059, 20364, 7639, '<td valign="top">I wouldn''t want to be the painter.  Colorful shot.</td>', 'I wouldn''t want to be the painter.  Colorful shot.', '2003-05-06 11:33:48.000000', NULL, 1),
(289060, 20518, 3791, '<td valign="top">If I go to NY one day, I hope to see your postcard for sale somewhere...</td>', 'If I go to NY one day, I hope to see your postcard for sale somewhere...', '2003-05-06 11:34:04.000000', NULL, 1),
(289061, 20280, 5112, '<td valign="top">Good postcard, the clouds in the sky are beautiful!  Two small comments: (1) I find the words at the bottom a bit hard to read (they get lost on my screen); (2) The mountains/clouds look almost too sharp to my eye (again, might be my screen).  Good work!  ~8</td>', 'Good postcard, the clouds in the sky are beautiful!  Two small comments: (1) I find the words at the bottom a bit hard to read (they get lost on my screen); (2) The mountains/clouds look almost too sharp to my eye (again, might be my screen).  Good work!  ~8', '2003-05-06 11:34:06.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(289062, 20168, 7639, '<td valign="top">Wonderful lines.</td>', 'Wonderful lines.', '2003-05-06 11:35:43.000000', NULL, 1),
(289063, 20504, 5112, '<td valign="top">I love the old/new juxtaposition!  Personally I wish the sky were bluer (weather is so fickle!) and the light brighter.  Also, I wonder if placing the word "Dallas" so that it somehow connects the old and the new building would be more effective?</td>', 'I love the old/new juxtaposition!  Personally I wish the sky were bluer (weather is so fickle!) and the light brighter.  Also, I wonder if placing the word "Dallas" so that it somehow connects the old and the new building would be more effective?', '2003-05-06 11:36:29.000000', NULL, 1),
(289065, 20454, 5112, '<td valign="top">It does look like one of the old coloured postcards!  Very nice.  I think maybe the green words (Wish you were here!) do not match the "old" look of the card, the small "California Foothills" does.  The font of the green letters looks "newer" to me.</td>', 'It does look like one of the old coloured postcards!  Very nice.  I think maybe the green words (Wish you were here!) do not match the "old" look of the card, the small "California Foothills" does.  The font of the green letters looks "newer" to me.', '2003-05-06 11:38:13.000000', NULL, 1),
(289067, 20112, 7639, '<td valign="top">I like the faded colors.</td>', 'I like the faded colors.', '2003-05-06 11:38:42.000000', NULL, 1),
(289068, 20462, 5728, '<td valign="top">Typical postcard shot, well done. The composition/cropping are ideal and the framing and text fit well to the image. Not too sure about the magenta tint in the clouds tho.</td>', 'Typical postcard shot, well done. The composition/cropping are ideal and the framing and text fit well to the image. Not too sure about the magenta tint in the clouds tho.', '2003-05-06 11:38:42.000000', NULL, 1),
(289073, 20268, 7639, '<td valign="top">Makes me want to reach in and grab a slice.</td>', 'Makes me want to reach in and grab a slice.', '2003-05-06 11:41:50.000000', NULL, 1),
(289074, 20511, 5728, '<td valign="top">I like this image a lot you have composed it very well. The yellows contrast very well against the bland background. This would make an excellent postcard. From your title, and the lack of a description on your postcard I am not sure what or where it really is. Is this promoting the area you live in? If so I need more information - 7.</td>', 'I like this image a lot you have composed it very well. The yellows contrast very well against the bland background. This would make an excellent postcard. From your title, and the lack of a description on your postcard I am not sure what or where it really is. Is this promoting the area you live in? If so I need more information - 7.', '2003-05-06 11:43:39.000000', NULL, 1),
(289075, 19993, 7639, '<td valign="top">What did you do to the plant?  Interesting subject.</td>', 'What did you do to the plant?  Interesting subject.', '2003-05-06 11:44:19.000000', NULL, 1),
(289077, 20414, 7639, '<td valign="top">You could have cropped out the pole.  I live nearby.<br/></td>', 'You could have cropped out the pole.  I live nearby.', '2003-05-06 11:46:27.000000', NULL, 1),
(289081, 20422, 7639, '<td valign="top">Worthy of the National Geographic.</td>', 'Worthy of the National Geographic.', '2003-05-06 11:48:15.000000', NULL, 1),
(289082, 20417, 7639, '<td valign="top">Gemlike.</td>', 'Gemlike.', '2003-05-06 11:50:09.000000', NULL, 1),
(289086, 20370, 8200, '<td valign="top">Great Photo Kosta!</td>', 'Great Photo Kosta!', '2003-05-06 11:54:31.000000', NULL, 1),
(289087, 20078, 5728, '<td valign="top">Good example of a postcard, maybe using a polarizer filter, or tweaking the curves or saturation in the post processing might have brought those colors out a lot more. Other than that, good idea.</td>', 'Good example of a postcard, maybe using a polarizer filter, or tweaking the curves or saturation in the post processing might have brought those colors out a lot more. Other than that, good idea.', '2003-05-06 11:55:28.000000', NULL, 1),
(289089, 20120, 5728, '<td valign="top">I met a girl from Portland a long time ago, we had a good time so just for that you get an extra point :-) Good composition here, taken from a bridge I guess? And of course it just reeks "postcard"!</td>', 'I met a girl from Portland a long time ago, we had a good time so just for that you get an extra point :-) Good composition here, taken from a bridge I guess? And of course it just reeks "postcard"!', '2003-05-06 11:57:25.000000', NULL, 1),
(289100, 19993, 5728, '<td valign="top">This is a very lively pic, lots of color. It was a good idea to take a photo with a sign already in it so it wasn''t necessary to add text to it. Some pics in this challenge have been killed by the text they added.</td>', 'This is a very lively pic, lots of color. It was a good idea to take a photo with a sign already in it so it wasn''t necessary to add text to it. Some pics in this challenge have been killed by the text they added.', '2003-05-06 12:09:17.000000', NULL, 1),
(289102, 20154, 6667, '<td valign="top">Oh! if only the Delta Queen had been goiing by!  Nice shot.</td>', 'Oh! if only the Delta Queen had been goiing by!  Nice shot.', '2003-05-06 12:11:01.000000', NULL, 1),
(289103, 20449, 5728, '<td valign="top">This is a good photo, the texture of the water is amazing! Well composed, nice combination of colors, I like it. The text, in my opinion, could have been placed more in the lower left hand corner tho.</td>', 'This is a good photo, the texture of the water is amazing! Well composed, nice combination of colors, I like it. The text, in my opinion, could have been placed more in the lower left hand corner tho.', '2003-05-06 12:11:30.000000', NULL, 1),
(289105, 20161, 5728, '<td valign="top">Okay. You''ve got me convinced! I''m packing my bags and coming visiting you in Arkansas! Okay?<br/> <br/>This is a very picturesque and typical postcard image. Very inviting indeed, you have a good eye. Don''t forget to pick me up at the airport!</td>', 'Okay. You''ve got me convinced! I''m packing my bags and coming visiting you in Arkansas! Okay? This is a very picturesque and typical postcard image. Very inviting indeed, you have a good eye. Don''t forget to pick me up at the airport!', '2003-05-06 12:13:55.000000', NULL, 1),
(289108, 20363, 5728, '<td valign="top">Isn''t this the Rapunzel tower where she lets down her hair? Interesting composition, the purple comes out well. WIsh I knew where it is though!</td>', 'Isn''t this the Rapunzel tower where she lets down her hair? Interesting composition, the purple comes out well. WIsh I knew where it is though!', '2003-05-06 12:15:28.000000', NULL, 1),
(289111, 20168, 7758, '<td valign="top">nice shot, I like the visual impact while still representing an iconic landmark of the area. it would definately make for a good postcard. One thing I noticed though is a certain amout of ''grain'' in the sky seems to be picking up a certain amount of red. Overall though I really like it.... 9 one of my faves this week.</td>', 'nice shot, I like the visual impact while still representing an iconic landmark of the area. it would definately make for a good postcard. One thing I noticed though is a certain amout of ''grain'' in the sky seems to be picking up a certain amount of red. Overall though I really like it.... 9 one of my faves this week.', '2003-05-06 12:18:29.000000', NULL, 1),
(289115, 20518, 5728, '<td valign="top">Good idea! Whenever I think of New York cabs are one of the first things I think of. You have done it well in a awesome panning shot and a fitting title, good luck!</td>', 'Good idea! Whenever I think of New York cabs are one of the first things I think of. You have done it well in a awesome panning shot and a fitting title, good luck!', '2003-05-06 12:20:16.000000', NULL, 1),
(289122, 20428, 772, '<td valign="top">This is an excellent image... I love the quaint city setting and the empty streets and walkways... I think the toning is just a bit heavy though... excellent image :)</td>', 'This is an excellent image... I love the quaint city setting and the empty streets and walkways... I think the toning is just a bit heavy though... excellent image :)', '2003-05-06 12:25:00.000000', NULL, 1),
(289128, 20138, 6667, '<td valign="top">Love the various shades and shapes. Very nice shot. . . and that''s comming from a Clevelander too!</td>', 'Love the various shades and shapes. Very nice shot. . . and that''s comming from a Clevelander too!', '2003-05-06 12:38:19.000000', NULL, 1),
(289134, 20439, 6667, '<td valign="top">Very clean shot.  Love the subtle shades of blue.  little less of the river maybe?</td>', 'Very clean shot.  Love the subtle shades of blue.  little less of the river maybe?', '2003-05-06 12:45:28.000000', NULL, 1),
(289137, 20383, 6667, '<td valign="top">Damn that one street light!  Very pretty.  I wish the town name was written in a little more prominent font or size.</td>', 'Damn that one street light!  Very pretty.  I wish the town name was written in a little more prominent font or size.', '2003-05-06 12:48:20.000000', NULL, 1),
(289138, 20363, 8488, '<td valign="top">I love the color/black-and-white contrast.</td>', 'I love the color/black-and-white contrast.', '2003-05-06 12:48:38.000000', NULL, 1),
(289140, 20449, 8488, '<td valign="top">Well, it DOES look like a postcard ... but it''s kind of an ugly postcard. Not that there aren''t a lot of those!</td>', 'Well, it DOES look like a postcard ... but it''s kind of an ugly postcard. Not that there aren''t a lot of those!', '2003-05-06 12:49:04.000000', NULL, 1),
(289142, 20332, 8488, '<td valign="top">This would never be an actual postcard - too experimental, too raw. Pretty, but not for this topic, IMHO.</td>', 'This would never be an actual postcard - too experimental, too raw. Pretty, but not for this topic, IMHO.', '2003-05-06 12:50:07.000000', NULL, 1),
(289145, 20262, 6667, '<td valign="top">With all that space. . . no writing?!!!</td>', 'With all that space. . . no writing?!!!', '2003-05-06 12:51:17.000000', NULL, 1),
(289146, 20335, 8488, '<td valign="top">Too pretty for a real postcard, but man I like it.</td>', 'Too pretty for a real postcard, but man I like it.', '2003-05-06 12:51:27.000000', NULL, 1),
(289149, 20268, 8488, '<td valign="top">I somehow don''t see this as an actual postcard on a rack somewhere. Nice image, though.</td>', 'I somehow don''t see this as an actual postcard on a rack somewhere. Nice image, though.', '2003-05-06 12:53:42.000000', NULL, 1),
(289150, 20419, 8488, '<td valign="top">Didn''t I *buy* that postcard? :-&gt;</td>', 'Didn''t I *buy* that postcard? :->', '2003-05-06 12:54:45.000000', NULL, 1),
(289155, 20386, 8488, '<td valign="top">I''ve never seen a postcard with quite that aspect ratio (though it''s a lovely image).</td>', 'I''ve never seen a postcard with quite that aspect ratio (though it''s a lovely image).', '2003-05-06 12:58:42.000000', NULL, 1),
(289160, 20375, 8488, '<td valign="top">A little more contrast in color between the tractor and the buttes in the background would make this a far better picture.</td>', 'A little more contrast in color between the tractor and the buttes in the background would make this a far better picture.', '2003-05-06 13:02:12.000000', NULL, 1),
(289163, 20439, 8488, '<td valign="top">I swear, I''ve bought this postcard before. :-&gt; Well done! Right in the style of the genre.</td>', 'I swear, I''ve bought this postcard before. :-> Well done! Right in the style of the genre.', '2003-05-06 13:04:56.000000', NULL, 1),
(289165, 20516, 1379, '<td valign="top">Nice photo, but I don''t really like your choice of text... That yellow is kind of harsh agains the stately quality of the building, IMO.</td>', 'Nice photo, but I don''t really like your choice of text... That yellow is kind of harsh agains the stately quality of the building, IMO.', '2003-05-06 13:08:00.000000', NULL, 1),
(289166, 20269, 1379, '<td valign="top">Wow!  That blue sky really pops out!  Cool!</td>', 'Wow!  That blue sky really pops out!  Cool!', '2003-05-06 13:08:27.000000', NULL, 1),
(289167, 20435, 1379, '<td valign="top">Nice catch of that little moth/ butterfly!  I love the Texas hill country!</td>', 'Nice catch of that little moth/ butterfly!  I love the Texas hill country!', '2003-05-06 13:09:01.000000', NULL, 1),
(289170, 20462, 1379, '<td valign="top">Beautiful Buddah.  I especially like that rich green in the background.  Too bad the sculpted flowers were not able to fit into your frame.</td>', 'Beautiful Buddah.  I especially like that rich green in the background.  Too bad the sculpted flowers were not able to fit into your frame.', '2003-05-06 13:11:16.000000', NULL, 1),
(289172, 19823, 1379, '<td valign="top">Yup, that looks like a small town kind of postcard!  That cellphone tower in the background must be the ND state tree, right?  :-)</td>', 'Yup, that looks like a small town kind of postcard!  That cellphone tower in the background must be the ND state tree, right?  :-)', '2003-05-06 13:12:20.000000', NULL, 1),
(289173, 20363, 1379, '<td valign="top">Pretty, and imposing, all at once.  Some text to give context would have helped...</td>', 'Pretty, and imposing, all at once.  Some text to give context would have helped...', '2003-05-06 13:13:14.000000', NULL, 1),
(289174, 20446, 1379, '<td valign="top">Lovely!  What a pastoral scene you captured!  That plaque of Texas is really dramatic. I''d buy this postcard!</td>', 'Lovely!  What a pastoral scene you captured!  That plaque of Texas is really dramatic. I''d buy this postcard!', '2003-05-06 13:14:05.000000', NULL, 1),
(289176, 20213, 1379, '<td valign="top">Splendor!!  I would love to visit this place and stand right where you are!  How lovely!</td>', 'Splendor!!  I would love to visit this place and stand right where you are!  How lovely!', '2003-05-06 13:14:36.000000', NULL, 1),
(289178, 20442, 1379, '<td valign="top">Truly looks like a postcard.  A real bargain at 20 cents!  Great shot.</td>', 'Truly looks like a postcard.  A real bargain at 20 cents!  Great shot.', '2003-05-06 13:15:15.000000', NULL, 1),
(289179, 20331, 1379, '<td valign="top">Wow!  So moody!  I don''t know if I would buy this as a postcard, but it''s definitely a high-quality piece of art.  Very cool!</td>', 'Wow!  So moody!  I don''t know if I would buy this as a postcard, but it''s definitely a high-quality piece of art.  Very cool!', '2003-05-06 13:15:48.000000', NULL, 1),
(289180, 20120, 1379, '<td valign="top">Ooooh, I like that sweeping curve of wood against the green of the grass.  Nice!</td>', 'Ooooh, I like that sweeping curve of wood against the green of the grass.  Nice!', '2003-05-06 13:16:24.000000', NULL, 1),
(289181, 20353, 1379, '<td valign="top">This makes me think of SF in the rough....  It really is a place with a lot of grit to enhance the texture of things.  Your inclusion of graffitti was clever!</td>', 'This makes me think of SF in the rough....  It really is a place with a lot of grit to enhance the texture of things.  Your inclusion of graffitti was clever!', '2003-05-06 13:17:11.000000', NULL, 1),
(289182, 20332, 1379, '<td valign="top">Awesome idea, but the fire eater himself is kind of lost in the shadows...  I know this must have been a difficult photo to get.</td>', 'Awesome idea, but the fire eater himself is kind of lost in the shadows...  I know this must have been a difficult photo to get.', '2003-05-06 13:17:57.000000', NULL, 1),
(289183, 20427, 1379, '<td valign="top">Funny and interesting, but not a polished enough composition for a real postcard, IMO.</td>', 'Funny and interesting, but not a polished enough composition for a real postcard, IMO.', '2003-05-06 13:18:43.000000', NULL, 1),
(289185, 20422, 1379, '<td valign="top">HOLY COW................      This is WAY too cool for a postcard!!!  This is like a shot from National Geographic!  This guy''s expression is incredible, and the colors and composition are intense.  Wow...  Can''t wait to make this one of my favorites.</td>', 'HOLY COW................      This is WAY too cool for a postcard!!!  This is like a shot from National Geographic!  This guy''s expression is incredible, and the colors and composition are intense.  Wow...  Can''t wait to make this one of my favorites.', '2003-05-06 13:19:56.000000', NULL, 1),
(289188, 20437, 1379, '<td valign="top">Whooo.... those clean lines and simple composition add up to make this an awesome photo.  Nice light!  I give you 10.</td>', 'Whooo.... those clean lines and simple composition add up to make this an awesome photo.  Nice light!  I give you 10.', '2003-05-06 13:21:40.000000', NULL, 1),
(289189, 20379, 1379, '<td valign="top">Such a lush landscape.  I would like to stay there!  Nice choice of font, too.</td>', 'Such a lush landscape.  I would like to stay there!  Nice choice of font, too.', '2003-05-06 13:22:09.000000', NULL, 1),
(289191, 20439, 1379, '<td valign="top">Yup, classic postcard!  Very nice, with the blue/ blue.  Too bad Toronto''s not greener at this time of year.  I''ll bet those trees look awesome once they''ve grown in.</td>', 'Yup, classic postcard!  Very nice, with the blue/ blue.  Too bad Toronto''s not greener at this time of year.  I''ll bet those trees look awesome once they''ve grown in.', '2003-05-06 13:23:25.000000', NULL, 1),
(289192, 20424, 1379, '<td valign="top">Scary!  Those are some strange animals!</td>', 'Scary!  Those are some strange animals!', '2003-05-06 13:24:07.000000', NULL, 1),
(289194, 20454, 1379, '<td valign="top">Beautiful shot..... Your title is a little unusual to me, though, because your choice of font is really not in the spirit of the early 1900''s.  However, I do love the greens and browns of your composition.  Great textures.</td>', 'Beautiful shot..... Your title is a little unusual to me, though, because your choice of font is really not in the spirit of the early 1900''s.  However, I do love the greens and browns of your composition.  Great textures.', '2003-05-06 13:25:25.000000', NULL, 1),
(289196, 20280, 1379, '<td valign="top">I love it!  The way that rooftop mirrors the mountain is really appealing, and the text, "WOMANS TONIC" is just hilarious.  What a funny card!  I''d buy it!</td>', 'I love it!  The way that rooftop mirrors the mountain is really appealing, and the text, "WOMANS TONIC" is just hilarious.  What a funny card!  I''d buy it!', '2003-05-06 13:28:44.000000', NULL, 1),
(289198, 20210, 1379, '<td valign="top">Oh, how I love Monterey Bay....  You did a great job of capturing the little tidepools right there.  Awesome shot, especially with those little flowers in the foreground.</td>', 'Oh, how I love Monterey Bay....  You did a great job of capturing the little tidepools right there.  Awesome shot, especially with those little flowers in the foreground.', '2003-05-06 13:29:37.000000', NULL, 1),
(289199, 20270, 1379, '<td valign="top">Interesting.... the Pegasus is being pinched by those two buildings...  I like your red frame.</td>', 'Interesting.... the Pegasus is being pinched by those two buildings...  I like your red frame.', '2003-05-06 13:30:35.000000', NULL, 1),
(289200, 20168, 1379, '<td valign="top">Yeah, that''s awesome!  I was never really aware of the TEXTURE of that thing, and you captured it here.  Very cool and non-traditional.  I love it!</td>', 'Yeah, that''s awesome!  I was never really aware of the TEXTURE of that thing, and you captured it here.  Very cool and non-traditional.  I love it!', '2003-05-06 13:31:16.000000', NULL, 1),
(289201, 20412, 1379, '<td valign="top">Moody.... Those two tall buildings look like angry robots in that burning sky.  Very imposing.</td>', 'Moody.... Those two tall buildings look like angry robots in that burning sky.  Very imposing.', '2003-05-06 13:32:06.000000', NULL, 1),
(289202, 20298, 1379, '<td valign="top">Wow... that plain of flowers is incredible.  I wish there were a little more definition in those trees back there.  Very nice.</td>', 'Wow... that plain of flowers is incredible.  I wish there were a little more definition in those trees back there.  Very nice.', '2003-05-06 13:33:05.000000', NULL, 1),
(289203, 20154, 1379, '<td valign="top">Incredible.  Your choice of font and text really works well with this glorious scene.</td>', 'Incredible.  Your choice of font and text really works well with this glorious scene.', '2003-05-06 13:33:56.000000', NULL, 1),
(289204, 20457, 2764, '<td valign="top">straighten the horison and come back when there isn''t such a big shadow on the beach</td>', 'straighten the horison and come back when there isn''t such a big shadow on the beach', '2003-05-06 13:34:33.000000', NULL, 1),
(289206, 20411, 1379, '<td valign="top">That''s amazing that you captured this with NO people in the shot!  It''s really lovely, and those greens are really incredible.  Nice.</td>', 'That''s amazing that you captured this with NO people in the shot!  It''s really lovely, and those greens are really incredible.  Nice.', '2003-05-06 13:35:11.000000', NULL, 1),
(289207, 19993, 2764, '<td valign="top">straighten it - everything leans right<br/></td>', 'straighten it - everything leans right', '2003-05-06 13:35:22.000000', NULL, 1),
(289209, 20456, 1379, '<td valign="top">Gee, could you have asked for a better sky?  This picture is awesome, and I can''t think of a single thing you could do to make this better.  It''s great!</td>', 'Gee, could you have asked for a better sky?  This picture is awesome, and I can''t think of a single thing you could do to make this better.  It''s great!', '2003-05-06 13:37:29.000000', NULL, 1),
(289210, 20364, 1379, '<td valign="top">Nice red!</td>', 'Nice red!', '2003-05-06 13:37:49.000000', NULL, 1),
(289211, 20519, 2764, '<td valign="top">The more interesting elements are off to the sides and the least interesting have been given center stage - try a different angle.</td>', 'The more interesting elements are off to the sides and the least interesting have been given center stage - try a different angle.', '2003-05-06 13:38:17.000000', NULL, 1),
(289212, 20240, 2764, '<td valign="top">straighten it</td>', 'straighten it', '2003-05-06 13:38:44.000000', NULL, 1),
(289213, 20478, 1379, '<td valign="top">I love that effect on the falls... so silky.  Your font (choice and color) are a little unusual, though.... But the photo itself is cool!</td>', 'I love that effect on the falls... so silky.  Your font (choice and color) are a little unusual, though.... But the photo itself is cool!', '2003-05-06 13:39:03.000000', NULL, 1),
(289216, 20535, 2764, '<td valign="top">Nice text, but does the photo "say" florida?  Could be almost anywhere,</td>', 'Nice text, but does the photo "say" florida?  Could be almost anywhere,', '2003-05-06 13:39:46.000000', NULL, 1),
(289217, 20336, 1379, '<td valign="top">Beautiful.  That green really enhances the entire shot.  I need to visit this place.</td>', 'Beautiful.  That green really enhances the entire shot.  I need to visit this place.', '2003-05-06 13:40:44.000000', NULL, 1),
(289218, 20528, 1379, '<td valign="top">Awesome sky to go with your hotel!</td>', 'Awesome sky to go with your hotel!', '2003-05-06 13:41:04.000000', NULL, 1),
(289219, 20517, 2764, '<td valign="top">when it''s over, clone out the little building in front - it''s distracting/</td>', 'when it''s over, clone out the little building in front - it''s distracting/', '2003-05-06 13:41:11.000000', NULL, 1),
(289220, 20442, 2764, '<td valign="top">the horizon is slightly tilted - my pet peeve of the week</td>', 'the horizon is slightly tilted - my pet peeve of the week', '2003-05-06 13:42:44.000000', NULL, 1),
(289222, 20543, 2764, '<td valign="top">chop dpwn some trees</td>', 'chop dpwn some trees', '2003-05-06 13:43:24.000000', NULL, 1),
(289225, 20478, 2764, '<td valign="top">nice photo - ugly lettering</td>', 'nice photo - ugly lettering', '2003-05-06 13:44:33.000000', NULL, 1),
(289227, 20518, 2764, '<td valign="top">Great photo - I wouldn''t buy the postcard though</td>', 'Great photo - I wouldn''t buy the postcard though', '2003-05-06 13:45:09.000000', NULL, 1),
(289228, 20540, 2764, '<td valign="top">too tilted</td>', 'too tilted', '2003-05-06 13:46:07.000000', NULL, 1),
(289233, 20332, 8286, '<td valign="top">Beautiful angle, but the saturation and pixilization are distracting over all.</td>', 'Beautiful angle, but the saturation and pixilization are distracting over all.', '2003-05-06 13:55:34.000000', NULL, 1),
