(291690, 20442, 6900, '<td valign="top">THE most scenic of the scenery shots.  I wish there was some bird or person or lighthouse  to catch our attention on - but this is beautiful. 10.</td>', 'THE most scenic of the scenery shots.  I wish there was some bird or person or lighthouse  to catch our attention on - but this is beautiful. 10.', '2003-05-08 01:56:57.000000', NULL, 1),
(291695, 20427, 6900, '<td valign="top">Not sure how this sells your town very well.  The main subject is facing the wrong way.  A bit washed out, too.  Good try!</td>', 'Not sure how this sells your town very well.  The main subject is facing the wrong way.  A bit washed out, too.  Good try!', '2003-05-08 02:06:31.000000', NULL, 1),
(291696, 20511, 6900, '<td valign="top">This is a good picture - I''m not sure how good of a postcard it is.  It doesn''t look appealing - with the one flower bent over and stuff.</td>', 'This is a good picture - I''m not sure how good of a postcard it is.  It doesn''t look appealing - with the one flower bent over and stuff.', '2003-05-08 02:07:57.000000', NULL, 1),
(291697, 20270, 6900, '<td valign="top">Does not scream "Dallas!" to me - except the very cool border.</td>', 'Does not scream "Dallas!" to me - except the very cool border.', '2003-05-08 02:08:38.000000', NULL, 1),
(291698, 20519, 6900, '<td valign="top">I think it''s a bit dark and the text is too much.  THe building on the right is cool - the ones on the left are a bit too dark to see much detail.</td>', 'I think it''s a bit dark and the text is too much.  THe building on the right is cool - the ones on the left are a bit too dark to see much detail.', '2003-05-08 02:10:25.000000', NULL, 1),
(291699, 20424, 6900, '<td valign="top">This says to me "backyard."  Not "my town."  The perspective is cool - but the flowers are a bit too blurred out and your focus is on the grass in the center, not on any of the cows.  I''d try a longer DoF and focus on the 3 cows on the right.</td>', 'This says to me "backyard."  Not "my town."  The perspective is cool - but the flowers are a bit too blurred out and your focus is on the grass in the center, not on any of the cows.  I''d try a longer DoF and focus on the 3 cows on the right.', '2003-05-08 02:13:05.000000', NULL, 1),
(291700, 20112, 6900, '<td valign="top">Love the perspective - not fond of the colors.</td>', 'Love the perspective - not fond of the colors.', '2003-05-08 02:13:35.000000', NULL, 1),
(291701, 20386, 6900, '<td valign="top">Interesting viewpoint on this.  I like the coloring but it seems a bit unreal...oversaturated perhaps.</td>', 'Interesting viewpoint on this.  I like the coloring but it seems a bit unreal...oversaturated perhaps.', '2003-05-08 02:15:19.000000', NULL, 1),
(291705, 20168, 7711, '<td valign="top">great angle on an oft photographed landmark. :) I love the consistent blue tones as well. My only gripe is the font..its not adding anything to the style of your photo..still a great shot though!</td>', 'great angle on an oft photographed landmark. :) I love the consistent blue tones as well. My only gripe is the font..its not adding anything to the style of your photo..still a great shot though!', '2003-05-08 02:22:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(291706, 20161, 7711, '<td valign="top">I like that you kept more of the creek to give yourself space to write the text, but the font and colour don''t stand out enough from the water, and the tall leaves/grass distract from the quaintness of the mill.</td>', 'I like that you kept more of the creek to give yourself space to write the text, but the font and colour don''t stand out enough from the water, and the tall leaves/grass distract from the quaintness of the mill.', '2003-05-08 02:23:49.000000', NULL, 1),
(291707, 20434, 7711, '<td valign="top">super composition! the line of boats and buildings are just perfect. but..overexposed/too bright, and in the end, the shot seems a bit harsh and perhaps even too sharp. Was there a lot of post-processing done?</td>', 'super composition! the line of boats and buildings are just perfect. but..overexposed/too bright, and in the end, the shot seems a bit harsh and perhaps even too sharp. Was there a lot of post-processing done?', '2003-05-08 02:25:48.000000', NULL, 1),
(291708, 20370, 7711, '<td valign="top">beautiful geometry and colours. I think you shot this at the just the right time of day to capture a lighter blue sky and the lights as well. well done!</td>', 'beautiful geometry and colours. I think you shot this at the just the right time of day to capture a lighter blue sky and the lights as well. well done!', '2003-05-08 02:27:55.000000', NULL, 1),
(291710, 20437, 7711, '<td valign="top">magnficient and uncluttered by your text. What gorgeous composition lighting and focus and textures!</td>', 'magnficient and uncluttered by your text. What gorgeous composition lighting and focus and textures!', '2003-05-08 02:33:20.000000', NULL, 1),
(291718, 20379, 2586, '<td valign="top">I read that forum thread and then your profile so i know who did this :) I find this shot warm and endearing. I guess one of the purposes of a postcard is that the recipient wished he/she could visit there. Yes, this postcard makes me want to visit Chorley so you have accomplished your mission! I like the vantage point from which you took this shot as it gives a glimpse of the country and thus enables the viewer to "guess" the whole feeling of the countryside over there. Movies and books where the ending leaves room for a lot of speculation, or are unresolved, are often much  more interesting than those where it is all spelled out for the ''dumb'' audience.<br/>And yeah, i can say something about cropping out the road there but you took the shot and made that decision because there was something less desireable on the left that you wanted to keep out at all cost. And next to that road is that lovely tree. Also, that road leads my fantasy right into my speculative countryside wanderings so it''s actually a good thing it is there.  I appreciate pictures that inspire me to dream away; this one does. 8</td>', 'I read that forum thread and then your profile so i know who did this :) I find this shot warm and endearing. I guess one of the purposes of a postcard is that the recipient wished he/she could visit there. Yes, this postcard makes me want to visit Chorley so you have accomplished your mission! I like the vantage point from which you took this shot as it gives a glimpse of the country and thus enables the viewer to "guess" the whole feeling of the countryside over there. Movies and books where the ending leaves room for a lot of speculation, or are unresolved, are often much  more interesting than those where it is all spelled out for the ''dumb'' audience.And yeah, i can say something about cropping out the road there but you took the shot and made that decision because there was something less desireable on the left that you wanted to keep out at all cost. And next to that road is that lovely tree. Also, that road leads my fantasy right into my speculative countryside wanderings so it''s actually a good thing it is there.  I appreciate pictures that inspire me to dream away; this one does. 8', '2003-05-08 03:14:05.000000', NULL, 1),
(291723, 20111, 2586, '<td valign="top">I like the original vantage point of this shot. If it weren''t for that famous bridge no one would ever guess this is NYC. Great to leave the ''beaten path'' for something as cliche as postcards. Triangles are one of my favorite shapes and i see a number of them hear; my eye dotes on them. 7</td>', 'I like the original vantage point of this shot. If it weren''t for that famous bridge no one would ever guess this is NYC. Great to leave the ''beaten path'' for something as cliche as postcards. Triangles are one of my favorite shapes and i see a number of them hear; my eye dotes on them. 7', '2003-05-08 03:18:26.000000', NULL, 1),
(291768, 20209, 3540, '<td valign="top">Wow, nice scenery.  A river, mountains, some nice trees... Its got it all. This pic lacks just a little sharpness.  Otherwise its a nice pic</td>', 'Wow, nice scenery.  A river, mountains, some nice trees... Its got it all. This pic lacks just a little sharpness.  Otherwise its a nice pic', '2003-05-08 05:54:30.000000', NULL, 1),
(291769, 20454, 3540, '<td valign="top">The differing textures of the hills is really cool.  This looks like a nice remote getaway.  I think the cloudy sky is pretty fitting too with this rough looking terrain.</td>', 'The differing textures of the hills is really cool.  This looks like a nice remote getaway.  I think the cloudy sky is pretty fitting too with this rough looking terrain.', '2003-05-08 05:57:37.000000', NULL, 1),
(291770, 20440, 3540, '<td valign="top">This shot needs to be leveled and the sky should be blue instead of white.   Not a bad looking building, but not much visual impact here either.</td>', 'This shot needs to be leveled and the sky should be blue instead of white.   Not a bad looking building, but not much visual impact here either.', '2003-05-08 05:59:18.000000', NULL, 1),
(291771, 20112, 3540, '<td valign="top">Good old looking photograph.  It really does have that ''50s feel to it with the black and white/sepia look to it.  It doesn''t really seem like one o the other definitely.  Nice balance to this photo with the framing but I think I''d like to see all of the building under the lighthouse.  Good pic despite.</td>', 'Good old looking photograph.  It really does have that ''50s feel to it with the black and white/sepia look to it.  It doesn''t really seem like one o the other definitely.  Nice balance to this photo with the framing but I think I''d like to see all of the building under the lighthouse.  Good pic despite.', '2003-05-08 06:01:18.000000', NULL, 1),
(291773, 20213, 3540, '<td valign="top">This looks a little too hazy for this shot.  The water is great as is the mountains, but I think its just not quite there yet.  Great scenery here though</td>', 'This looks a little too hazy for this shot.  The water is great as is the mountains, but I think its just not quite there yet.  Great scenery here though', '2003-05-08 06:03:40.000000', NULL, 1),
(291775, 20120, 3540, '<td valign="top">Not a bad photo.  I think the colors of this  one are a little weird, which may be the case for real.  The trees seem a little to yellow and I think the overall photo is just a little bright.   I wish it were just a fuzz sharper too.</td>', 'Not a bad photo.  I think the colors of this  one are a little weird, which may be the case for real.  The trees seem a little to yellow and I think the overall photo is just a little bright.   I wish it were just a fuzz sharper too.', '2003-05-08 06:06:07.000000', NULL, 1),
(291777, 20298, 3540, '<td valign="top">Now this is a postcard.   I haven''t seen too many that are that convincing, but this is one of the best.  Great colors, scenery, framing, balance to this shot.  Nice work -9</td>', 'Now this is a postcard.   I haven''t seen too many that are that convincing, but this is one of the best.  Great colors, scenery, framing, balance to this shot.  Nice work -9', '2003-05-08 06:07:29.000000', NULL, 1),
(291778, 20448, 3540, '<td valign="top">This has some really nice sky colors.  THe geyser is a great touch and that is one interesting concept for a building.  Pretty good photo.  Too bad that silly fence is there.</td>', 'This has some really nice sky colors.  THe geyser is a great touch and that is one interesting concept for a building.  Pretty good photo.  Too bad that silly fence is there.', '2003-05-08 06:08:52.000000', NULL, 1),
(291780, 20437, 3540, '<td valign="top">I''ve seen these columns before methinks.  Not sure I like this take on this building.  Where''d the bottom half go?  You did capture some good textures on the pillars.</td>', 'I''ve seen these columns before methinks.  Not sure I like this take on this building.  Where''d the bottom half go?  You did capture some good textures on the pillars.', '2003-05-08 06:10:40.000000', NULL, 1),
(291783, 20207, 3540, '<td valign="top">Good scenery.  Nice landscape shot.  I like the reflections in the water.  I only wish the sky was blue.  Other than that this is a fantastic shot.</td>', 'Good scenery.  Nice landscape shot.  I like the reflections in the water.  I only wish the sky was blue.  Other than that this is a fantastic shot.', '2003-05-08 06:13:32.000000', NULL, 1),
(291784, 20240, 3540, '<td valign="top">The sky is severely pixelated on this shot.  who the heck is manning the boat?  a free floater?  I hope not for the boat owner''s sake.  Nice scenery but lit lloks a little tilted off of the horizon, but it could be just an optical illusion.</td>', 'The sky is severely pixelated on this shot.  who the heck is manning the boat?  a free floater?  I hope not for the boat owner''s sake.  Nice scenery but lit lloks a little tilted off of the horizon, but it could be just an optical illusion.', '2003-05-08 06:15:27.000000', NULL, 1),
(291785, 20334, 3540, '<td valign="top">Nice job with this one.  NOT a landscape for once.  I think this is really well done and a really unusual effect used for this.  Great work -9</td>', 'Nice job with this one.  NOT a landscape for once.  I think this is really well done and a really unusual effect used for this.  Great work -9', '2003-05-08 06:16:33.000000', NULL, 1),
(291793, 20482, 8581, '<td valign="top">Outstanding useage of graphics and photo. Color and tone is right on. One of the best in my eyes.</td>', 'Outstanding useage of graphics and photo. Color and tone is right on. One of the best in my eyes.', '2003-05-08 06:56:24.000000', NULL, 1),
(291794, 20411, 3900, '<td valign="top">Nice, bright and vibrant colors.  I would like to see this at different times of the day to see how the shadows change the overall feel.  But it''s very nice how it is.</td>', 'Nice, bright and vibrant colors.  I would like to see this at different times of the day to see how the shadows change the overall feel.  But it''s very nice how it is.', '2003-05-08 06:59:08.000000', NULL, 1),
(291795, 20353, 8581, '<td valign="top">Way to busy. To much empty sky, the sign is the only point of intrest. A trite photo.</td>', 'Way to busy. To much empty sky, the sign is the only point of intrest. A trite photo.', '2003-05-08 07:01:34.000000', NULL, 1),
(291873, 20368, 5728, '<td valign="top">The stormy looking sky in the background with the magenta tinge does a lot for this pic. It took me a while to realise that the ferry was coming in this direction! Good postcard.</td>', 'The stormy looking sky in the background with the magenta tinge does a lot for this pic. It took me a while to realise that the ferry was coming in this direction! Good postcard.', '2003-05-08 09:35:19.000000', NULL, 1),
(291874, 20385, 5728, '<td valign="top">A good capture of a very serene and beautiful area. Simple but effective.</td>', 'A good capture of a very serene and beautiful area. Simple but effective.', '2003-05-08 09:36:08.000000', NULL, 1),
(291876, 20380, 5728, '<td valign="top">A very typical postcard shot. I like the pastel colors of the trees on the shore line. A polarizer filter might have brought those colors and the sky out a lot more, but otherwise a photo you can be proud of.</td>', 'A very typical postcard shot. I like the pastel colors of the trees on the shore line. A polarizer filter might have brought those colors and the sky out a lot more, but otherwise a photo you can be proud of.', '2003-05-08 09:37:46.000000', NULL, 1),
(291877, 20207, 5728, '<td valign="top">Okay okay, you have convinced me to come to Ottawa with your postcard :-) You have a very good eye, and the lighting is perfect. Late in the day or early in the morning?</td>', 'Okay okay, you have convinced me to come to Ottawa with your postcard :-) You have a very good eye, and the lighting is perfect. Late in the day or early in the morning?', '2003-05-08 09:42:21.000000', NULL, 1),
(291879, 20396, 5728, '<td valign="top">I can almost hear the waves sloshing up onto the shore, and that sky is so crisp and deep blue. This is a fantastic photo!</td>', 'I can almost hear the waves sloshing up onto the shore, and that sky is so crisp and deep blue. This is a fantastic photo!', '2003-05-08 09:44:09.000000', NULL, 1),
(291882, 20317, 5728, '<td valign="top">This looks like a typical English coastal town postcard shot, well thought out! The composition you chose is appealing and what strikes me immediately when I look at this image are the many different tones of light blue in it, good one!</td>', 'This looks like a typical English coastal town postcard shot, well thought out! The composition you chose is appealing and what strikes me immediately when I look at this image are the many different tones of light blue in it, good one!', '2003-05-08 09:46:37.000000', NULL, 1),
(291884, 20517, 5728, '<td valign="top">At first I thought that black dot was a spot on my monitor and tried to clean it off :-) But it is a bird isn''t it? Good shot, ideal angle and very promotional!</td>', 'At first I thought that black dot was a spot on my monitor and tried to clean it off :-) But it is a bird isn''t it? Good shot, ideal angle and very promotional!', '2003-05-08 09:51:40.000000', NULL, 1),
(291887, 20427, 5728, '<td valign="top">Interesting postcard shot, very original. The red and white arm is a little out of place though.</td>', 'Interesting postcard shot, very original. The red and white arm is a little out of place though.', '2003-05-08 09:53:18.000000', NULL, 1),
(291888, 20412, 5728, '<td valign="top">Awesome colors here, the sky looks really creepy with those clouds. This pic reminds me of a futuristic city out of some science fiction movie! Good night shot.</td>', 'Awesome colors here, the sky looks really creepy with those clouds. This pic reminds me of a futuristic city out of some science fiction movie! Good night shot.', '2003-05-08 09:55:38.000000', NULL, 1),
(291889, 20268, 5728, '<td valign="top">This is an excellent photo, very sharp and detailed. The lighting is bang on and the green and orange colors complement each other very well. I don''t think blue was the best color choice for the border though.</td>', 'This is an excellent photo, very sharp and detailed. The lighting is bang on and the green and orange colors complement each other very well. I don''t think blue was the best color choice for the border though.', '2003-05-08 09:57:20.000000', NULL, 1),
(291891, 20528, 5728, '<td valign="top">A very typical postcard shot I would expect to find in any postcard stand. What really makes this photo is the sky background with those amazing clouds in the distance.</td>', 'A very typical postcard shot I would expect to find in any postcard stand. What really makes this photo is the sky background with those amazing clouds in the distance.', '2003-05-08 09:59:05.000000', NULL, 1),
(291892, 20424, 5728, '<td valign="top">An original idea and you pulled it off well. I like the humourous aspect to it.</td>', 'An original idea and you pulled it off well. I like the humourous aspect to it.', '2003-05-08 10:00:20.000000', NULL, 1),
(291895, 20535, 5728, '<td valign="top">A wonderful sunset (sunrise?) photo. You really caught the light at the correct moment. You''ve depicted the coldness of the sky at the top of the image transforming into the warmth of the sunlit clouds as you go down. I like it. The text flow and positioning doesn''t really do much for me though.</td>', 'A wonderful sunset (sunrise?) photo. You really caught the light at the correct moment. You''ve depicted the coldness of the sky at the top of the image transforming into the warmth of the sunlit clouds as you go down. I like it. The text flow and positioning doesn''t really do much for me though.', '2003-05-08 10:03:56.000000', NULL, 1),
(291898, 20516, 7543, '<td valign="top">I''m not sure about the font, otherwise good</td>', 'I''m not sure about the font, otherwise good', '2003-05-08 10:06:58.000000', NULL, 1),
(291899, 20268, 7543, '<td valign="top">The frame color is a bit distracting, maybe it would be better to use the colors already there (orange, or green)</td>', 'The frame color is a bit distracting, maybe it would be better to use the colors already there (orange, or green)', '2003-05-08 10:07:53.000000', NULL, 1),
(291900, 20511, 7543, '<td valign="top">Excellent shot, the color of the flower is a great contrast to the black/gray tones. Flawless - a 10.</td>', 'Excellent shot, the color of the flower is a great contrast to the black/gray tones. Flawless - a 10.', '2003-05-08 10:10:13.000000', NULL, 1),
(291907, 20536, 5728, '<td valign="top">The stormy sky and angry clouds make for a decent background here. Who said all postcards MUST have a crisp blue sky as a background? You''ve gone against the rules of postcard regulations and showed them it can be done this way too, good one :-))))</td>', 'The stormy sky and angry clouds make for a decent background here. Who said all postcards MUST have a crisp blue sky as a background? You''ve gone against the rules of postcard regulations and showed them it can be done this way too, good one :-))))', '2003-05-08 10:19:20.000000', NULL, 1),
(291909, 20364, 5728, '<td valign="top">Good postcard shot. I especially like the way the white stands out against that vivid red color on the wheel, very effective. Good idea.</td>', 'Good postcard shot. I especially like the way the white stands out against that vivid red color on the wheel, very effective. Good idea.', '2003-05-08 10:20:35.000000', NULL, 1),
(291910, 20444, 5728, '<td valign="top">This is an interesting shot. The sky is a nice deep tone of blue which makes those kites (?) stand out more. I don''t know why but that bridge is a little disturbing, perhaps without it this would have been a lot more effective. Maybe you should have tried a few shots from the otherside of the bridge as well using a wide angle lens.</td>', 'This is an interesting shot. The sky is a nice deep tone of blue which makes those kites (?) stand out more. I don''t know why but that bridge is a little disturbing, perhaps without it this would have been a lot more effective. Maybe you should have tried a few shots from the otherside of the bridge as well using a wide angle lens.', '2003-05-08 10:24:09.000000', NULL, 1),
(291912, 20478, 7543, '<td valign="top">I think the font is too much, I would not use the inner bevel, plain text works better for my eyes. The shot is great!</td>', 'I think the font is too much, I would not use the inner bevel, plain text works better for my eyes. The shot is great!', '2003-05-08 10:25:23.000000', NULL, 1),
(291913, 20532, 5728, '<td valign="top">Typical postcard shot for sure. Somehow however the colors aren''t coming through as well as they should. You could have remedied this by adjusting the levels or saturation in a editing program. Good luck.</td>', 'Typical postcard shot for sure. Somehow however the colors aren''t coming through as well as they should. You could have remedied this by adjusting the levels or saturation in a editing program. Good luck.', '2003-05-08 10:26:06.000000', NULL, 1),
(291916, 20437, 7543, '<td valign="top">Great shot, good use of text - like it 8</td>', 'Great shot, good use of text - like it 8', '2003-05-08 10:28:03.000000', NULL, 1),
(291917, 20270, 5728, '<td valign="top">That is an original perspective! Good idea, especially with the sun shining on the right building and only shadows on the left one. The border is interesting although it isn''t enhancing this image much.</td>', 'That is an original perspective! Good idea, especially with the sun shining on the right building and only shadows on the left one. The border is interesting although it isn''t enhancing this image much.', '2003-05-08 10:28:44.000000', NULL, 1),
(291920, 20540, 5728, '<td valign="top">Is that the moon up there in the sky? You chose the right shutter speed for this image, those lights are bright but not blown out at all, good. I would have tried a few different variations on text style though, the one you chose looks a little bland.</td>', 'Is that the moon up there in the sky? You chose the right shutter speed for this image, those lights are bright but not blown out at all, good. I would have tried a few different variations on text style though, the one you chose looks a little bland.', '2003-05-08 10:31:17.000000', NULL, 1),
(291923, 20317, 7543, '<td valign="top">The colors seem a bit weird, saturation maybe too much?</td>', 'The colors seem a bit weird, saturation maybe too much?', '2003-05-08 10:33:54.000000', NULL, 1),
(291925, 20434, 7543, '<td valign="top">Meget godt</td>', 'Meget godt', '2003-05-08 10:36:40.000000', NULL, 1),
(291930, 20437, 2764, '<td valign="top">A perfect  10!  Both photo and lettering are perfect!</td>', 'A perfect  10!  Both photo and lettering are perfect!', '2003-05-08 10:50:39.000000', NULL, 1),
(291994, 20240, 7543, '<td valign="top">Maybe it''s just me, but it seems like the horizon is tilting towards the left side. A I wrong? Good pic, seagull does a whole lot. 7</td>', 'Maybe it''s just me, but it seems like the horizon is tilting towards the left side. A I wrong? Good pic, seagull does a whole lot. 7', '2003-05-08 11:30:29.000000', NULL, 1),
(291996, 20375, 7543, '<td valign="top">The tractor seems to blend in with the mountains, needs a bit of contrast between them for my taste. Good pic though</td>', 'The tractor seems to blend in with the mountains, needs a bit of contrast between them for my taste. Good pic though', '2003-05-08 11:32:08.000000', NULL, 1),
(292002, 20519, 7543, '<td valign="top">Eiki? Hef greinilega farið á mis við þetta safn.... Flott mynd</td>', 'Eiki? Hef greinilega farið á mis við þetta safn.... Flott mynd', '2003-05-08 11:38:02.000000', NULL, 1),
(292026, 20210, 6541, '<td valign="top">nice picture great color</td>', 'nice picture great color', '2003-05-08 12:07:43.000000', NULL, 1),
(292035, 20209, 7543, '<td valign="top">Could use some sharpening</td>', 'Could use some sharpening', '2003-05-08 12:20:13.000000', NULL, 1),
(292056, 20274, 5728, '<td valign="top">Good composition, just the sort of postcard I would expect to find in Valley City although I''ve never been there :-)</td>', 'Good composition, just the sort of postcard I would expect to find in Valley City although I''ve never been there :-)', '2003-05-08 12:30:15.000000', NULL, 1),
(292058, 20240, 5728, '<td valign="top">Lucky shot getting that seagull sitting on the boat. Your postcard gives out a very serene and peaceful impression.</td>', 'Lucky shot getting that seagull sitting on the boat. Your postcard gives out a very serene and peaceful impression.', '2003-05-08 12:31:26.000000', NULL, 1),
(292060, 20210, 5728, '<td valign="top">Good capture. The decision to go portrait works well in this pic.</td>', 'Good capture. The decision to go portrait works well in this pic.', '2003-05-08 12:33:01.000000', NULL, 1),
(292064, 20428, 5728, '<td valign="top">I love the old fashioned feeling your postcard creates. The change to sepia does wonders for this image, very nostalgic.</td>', 'I love the old fashioned feeling your postcard creates. The change to sepia does wonders for this image, very nostalgic.', '2003-05-08 12:34:28.000000', NULL, 1),
(292071, 20507, 5728, '<td valign="top">This is an original idea. The perspective is good, although I would have prefered a deeper DOF.</td>', 'This is an original idea. The perspective is good, although I would have prefered a deeper DOF.', '2003-05-08 12:39:13.000000', NULL, 1),
(292076, 20336, 7291, '<td valign="top">Close Encouters!  It DOES exist.  LOL!  Great shot.  Excellent color.  Sky could be a little clearer though.</td>', 'Close Encouters!  It DOES exist.  LOL!  Great shot.  Excellent color.  Sky could be a little clearer though.', '2003-05-08 12:41:37.000000', NULL, 1),
(292093, 20161, 1379, '<td valign="top">What a verdant, lush place!  I love your composition of this image.  The color of your text is a little off to me, but maybe that''s just my strange sense of color.  I love this shot!</td>', 'What a verdant, lush place!  I love your composition of this image.  The color of your text is a little off to me, but maybe that''s just my strange sense of color.  I love this shot!', '2003-05-08 12:51:46.000000', NULL, 1),
(292095, 20356, 1379, '<td valign="top">Looks like a real postcard to me!  I love the colors in this, and I think the black border really adds.</td>', 'Looks like a real postcard to me!  I love the colors in this, and I think the black border really adds.', '2003-05-08 12:52:34.000000', NULL, 1),
(292099, 20432, 1379, '<td valign="top">Totally picturesque.  You really got a nice shot of this place, free from the clutter of modern times.  That red is awesome!</td>', 'Totally picturesque.  You really got a nice shot of this place, free from the clutter of modern times.  That red is awesome!', '2003-05-08 12:55:34.000000', NULL, 1),
(292102, 20253, 1379, '<td valign="top">Ooooh, I like it!  I guess you used a mask of some kind to get that circle.  I love the b/w effect.  It really does look old-timey.</td>', 'Ooooh, I like it!  I guess you used a mask of some kind to get that circle.  I love the b/w effect.  It really does look old-timey.', '2003-05-08 12:56:45.000000', NULL, 1),
(292106, 20497, 1379, '<td valign="top">Those curves are incredible.  I love the negative space of the blue sky.  Great and abstract.</td>', 'Those curves are incredible.  I love the negative space of the blue sky.  Great and abstract.', '2003-05-08 12:57:42.000000', NULL, 1),
(292114, 20252, 1379, '<td valign="top">I am laughing at my desk!  This is so absurd!  I love it!</td>', 'I am laughing at my desk!  This is so absurd!  I love it!', '2003-05-08 13:03:01.000000', NULL, 1),
(292115, 20543, 1379, '<td valign="top">I love the color of the sky against that lovely brick.  What a great building to photograph!  The greens from the trees really add to the overall quality of the photo.</td>', 'I love the color of the sky against that lovely brick.  What a great building to photograph!  The greens from the trees really add to the overall quality of the photo.', '2003-05-08 13:03:59.000000', NULL, 1),
(292116, 20383, 1379, '<td valign="top">So tranquil and placid.  This photo would make a great puzzle, a 1000 piece!  Those reflections are amazing.</td>', 'So tranquil and placid.  This photo would make a great puzzle, a 1000 piece!  Those reflections are amazing.', '2003-05-08 13:05:05.000000', NULL, 1),
(292119, 20342, 1379, '<td valign="top">I love the perspective and the idea, but the blown-out spot in the center is distracting.  It must have been just that time of day...</td>', 'I love the perspective and the idea, but the blown-out spot in the center is distracting.  It must have been just that time of day...', '2003-05-08 13:06:01.000000', NULL, 1),
(292121, 20434, 1379, '<td valign="top">That rainbow of houses is great!  I love the busy quality to this shot.  It''s dense with details, balanced by the smoothness of the water on the right.</td>', 'That rainbow of houses is great!  I love the busy quality to this shot.  It''s dense with details, balanced by the smoothness of the water on the right.', '2003-05-08 13:07:04.000000', NULL, 1),
(292126, 20506, 1379, '<td valign="top">What an incredible sky.  Lovely and tranquil.</td>', 'What an incredible sky.  Lovely and tranquil.', '2003-05-08 13:09:12.000000', NULL, 1),
(292127, 20334, 1379, '<td valign="top">Weird effect you got, but it''s beautiful. It doesn''t look like a phograph any more.  You must have used a lot of filters or something?  The result is really interesting.  I''d buy this postcard!</td>', 'Weird effect you got, but it''s beautiful. It doesn''t look like a phograph any more.  You must have used a lot of filters or something?  The result is really interesting.  I''d buy this postcard!', '2003-05-08 13:10:09.000000', NULL, 1),
(292129, 20511, 7504, '<td valign="top">This is very artistic.  I love the mood of this shot, but not sure it''d make the best postcard.  If it''d been in the Flora challenge I wouldn''ve given it a 9 or 10.</td>', 'This is very artistic.  I love the mood of this shot, but not sure it''d make the best postcard.  If it''d been in the Flora challenge I wouldn''ve given it a 9 or 10.', '2003-05-08 13:10:34.000000', NULL, 1),
(292130, 20519, 1379, '<td valign="top">Glorious!  I was just visiting Iceland last month, and it was SO GREEN in places that it blew my mind.  Your photo takes me back!  I love the lushness of that grass.  It''s beautiful.</td>', 'Glorious!  I was just visiting Iceland last month, and it was SO GREEN in places that it blew my mind.  Your photo takes me back!  I love the lushness of that grass.  It''s beautiful.', '2003-05-08 13:11:25.000000', NULL, 1),
(292132, 20370, 1379, '<td valign="top">Flawless.  Your photo is not interrupted by anything extraneous.  This could be the winner.</td>', 'Flawless.  Your photo is not interrupted by anything extraneous.  This could be the winner.', '2003-05-08 13:12:26.000000', NULL, 1),
(292133, 20504, 1379, '<td valign="top">Wow, weird.  It''s a cool photo, but you must have done some interesting things to get this shot.  I like the contrast of the colors, warm against cool.  Strange but intriguing.</td>', 'Wow, weird.  It''s a cool photo, but you must have done some interesting things to get this shot.  I like the contrast of the colors, warm against cool.  Strange but intriguing.', '2003-05-08 13:14:08.000000', NULL, 1),
(292134, 20518, 1379, '<td valign="top">I love it!  I thought I already found my favorite in this challenge, but this might have replaced it!  Very clever and well-executed.  This is a postcard that I would actually buy.  Your use of literal cliche, rather than photographic cliche, is outstanding.</td>', 'I love it!  I thought I already found my favorite in this challenge, but this might have replaced it!  Very clever and well-executed.  This is a postcard that I would actually buy.  Your use of literal cliche, rather than photographic cliche, is outstanding.', '2003-05-08 13:15:29.000000', NULL, 1),
(292139, 20351, 1379, '<td valign="top">Interesting... This makes me think that Georgia is all about peanuts and.... time?  I must be missing something.</td>', 'Interesting... This makes me think that Georgia is all about peanuts and.... time?  I must be missing something.', '2003-05-08 13:16:35.000000', NULL, 1),
(292140, 20268, 1379, '<td valign="top">Oh that looks so good.  Your lighting really rocks.</td>', 'Oh that looks so good.  Your lighting really rocks.', '2003-05-08 13:17:07.000000', NULL, 1),
(292142, 20525, 1379, '<td valign="top">Poor fellas.  What is their fate?</td>', 'Poor fellas.  What is their fate?', '2003-05-08 13:18:08.000000', NULL, 1),
(292143, 20482, 1379, '<td valign="top">Great font choice for this.  It really mirrors the texture of the sculpture.  Awesome.</td>', 'Great font choice for this.  It really mirrors the texture of the sculpture.  Awesome.', '2003-05-08 13:18:43.000000', NULL, 1),
(292145, 20503, 1379, '<td valign="top">Wow, what a riot of color!  I love those colored reflections in the water.  Beautiful.</td>', 'Wow, what a riot of color!  I love those colored reflections in the water.  Beautiful.', '2003-05-08 13:19:33.000000', NULL, 1),
(292147, 19947, 1379, '<td valign="top">Sky-licious.  Beautiful.</td>', 'Sky-licious.  Beautiful.', '2003-05-08 13:20:00.000000', NULL, 1),
(292150, 20448, 1379, '<td valign="top">The pearl!  I was just in Island last month, and we could see that from our hotel.  I am ready to come back!</td>', 'The pearl!  I was just in Island last month, and we could see that from our hotel.  I am ready to come back!', '2003-05-08 13:20:48.000000', NULL, 1),
(292186, 20210, 3447, '<td valign="top">Very attractive composition and colors.  Text treatment is a nice touch.</td>', 'Very attractive composition and colors.  Text treatment is a nice touch.', '2003-05-08 14:11:01.000000', NULL, 1),
(292202, 20161, 3080, '<td valign="top">Beautiful.  Love the angle with the mill over to the right.  I also really like the railings of the bridge.  The grass in the front is perfect.  The focus seems a bit soft in places, I wonder if it was slightly windy?  Otherwise great job.  Just a suggestion, the writing is a little hard on the eyes.  Maybe a non cursive print would have worked better. ~Heather~</td>', 'Beautiful.  Love the angle with the mill over to the right.  I also really like the railings of the bridge.  The grass in the front is perfect.  The focus seems a bit soft in places, I wonder if it was slightly windy?  Otherwise great job.  Just a suggestion, the writing is a little hard on the eyes.  Maybe a non cursive print would have worked better. ~Heather~', '2003-05-08 14:47:49.000000', NULL, 1),
(292204, 20298, 3080, '<td valign="top">A lovely field.  Really pretty.  I like the angle and framing/cropping.  The lighting seems good.  The sky is a bit noisy.  Has speckles throughout it.  Otherwise, i''d buy this as a souvenier.  Great shot. ~Heather~</td>', 'A lovely field.  Really pretty.  I like the angle and framing/cropping.  The lighting seems good.  The sky is a bit noisy.  Has speckles throughout it.  Otherwise, i''d buy this as a souvenier.  Great shot. ~Heather~', '2003-05-08 14:49:36.000000', NULL, 1),
(292209, 20138, 3080, '<td valign="top">As a photo, I think this is nice.  As a post card though, I think that the sky is a little bland.  especially the upper left.  When we think of postcards, we think of the perfect world.  Realizing you only had a week to get ''the perfect sky'' and weather this time of year doesn''t always cooperate, I understand, but think that for a postcard, it should have a more interesting sky.  Also, the focus seems just a little soft.  Nothing real serious, but I wonder if this could be just a bit sharper. ~Heather~</td>', 'As a photo, I think this is nice.  As a post card though, I think that the sky is a little bland.  especially the upper left.  When we think of postcards, we think of the perfect world.  Realizing you only had a week to get ''the perfect sky'' and weather this time of year doesn''t always cooperate, I understand, but think that for a postcard, it should have a more interesting sky.  Also, the focus seems just a little soft.  Nothing real serious, but I wonder if this could be just a bit sharper. ~Heather~', '2003-05-08 14:52:33.000000', NULL, 1),
(292212, 20270, 7711, '<td valign="top">Its a great idea to use those pretty buildings to frame the pegasus, but its just too small and crowded by the buildings to stand out as much as it should.</td>', 'Its a great idea to use those pretty buildings to frame the pegasus, but its just too small and crowded by the buildings to stand out as much as it should.', '2003-05-08 14:53:26.000000', NULL, 1),
(292214, 20386, 3080, '<td valign="top">I would buy this as a souvenier.  I love the sky, and the rocks in the front really make this postcard worthy.  The angle and framing/cropping are good, and focus and clarity are also good.  The weather cooperated with you this day.  Good shot. ~Heather~</td>', 'I would buy this as a souvenier.  I love the sky, and the rocks in the front really make this postcard worthy.  The angle and framing/cropping are good, and focus and clarity are also good.  The weather cooperated with you this day.  Good shot. ~Heather~', '2003-05-08 14:54:12.000000', NULL, 1),
(292218, 20112, 7711, '<td valign="top">I think I would have liked to see this lighthouse against a different coloured sky. Maybe if it were a sunnier day, rather than overcast, or even a sunrise or something, just to add more colour to it. The brightness of the sky has the effect of making everything not white seem very dark and colourless.</td>', 'I think I would have liked to see this lighthouse against a different coloured sky. Maybe if it were a sunnier day, rather than overcast, or even a sunrise or something, just to add more colour to it. The brightness of the sky has the effect of making everything not white seem very dark and colourless.', '2003-05-08 14:56:13.000000', NULL, 1),
(292227, 20482, 3080, '<td valign="top">Lvoe it!  I love the angle and framing/cropping, the lighting is wonderful, and the focus and clarity are great as well.  A 10 from me this week.  I even really like where you put your text.  Just enough room without crowding it or the photo.  Great job. ~Heather~</td>', 'Lvoe it!  I love the angle and framing/cropping, the lighting is wonderful, and the focus and clarity are great as well.  A 10 from me this week.  I even really like where you put your text.  Just enough room without crowding it or the photo.  Great job. ~Heather~', '2003-05-08 15:05:52.000000', NULL, 1),
(292233, 20262, 3447, '<td valign="top">Nice reflection on water, and good color.<br/></td>', 'Nice reflection on water, and good color.', '2003-05-08 15:09:07.000000', NULL, 1),
(292236, 20395, 3447, '<td valign="top">Good composition, and nice color.</td>', 'Good composition, and nice color.', '2003-05-08 15:10:22.000000', NULL, 1),
(292242, 20411, 3447, '<td valign="top">I have paid good money for similar postcards.  Well done.  Sharp - good sky.</td>', 'I have paid good money for similar postcards.  Well done.  Sharp - good sky.', '2003-05-08 15:12:34.000000', NULL, 1),
(292247, 20168, 8488, '<td valign="top">Not a bad idea - I''ve seen postcards with that sort of concept/setup. However ... there really isn''t much contrast, at all. Everything''s almost exactly the same color of blue, and nothing''s really clear enough to give you somewhere to look. The text could also use to be bolder and postcardier, or omitted entirely (since as it is, it seems half-hearted and unsure, and just makes the overall effect worse). Maybe it''s cropped too close, or the angle is slightly too extreme.<br/> <br/>Sorry, just thinking out loud about how to explain my reactions. :-&gt;</td>', 'Not a bad idea - I''ve seen postcards with that sort of concept/setup. However ... there really isn''t much contrast, at all. Everything''s almost exactly the same color of blue, and nothing''s really clear enough to give you somewhere to look. The text could also use to be bolder and postcardier, or omitted entirely (since as it is, it seems half-hearted and unsure, and just makes the overall effect worse). Maybe it''s cropped too close, or the angle is slightly too extreme. Sorry, just thinking out loud about how to explain my reactions. :->', '2003-05-08 15:15:01.000000', NULL, 1),
(292249, 20395, 8488, '<td valign="top">Good concept, that''s a postcardy subject all right, but your contrast is pumped WAY high. The water is blinding white, the sky almost twilight-dark, and the whole thing is painful to look at. The water''s so bright you can''t really see anything on it - it washes out the detail, and drags your eye down to something that isn''t interesting to look at, rather than any actual focal point in the picture itself. The border and font label are just right for a postcard, though.</td>', 'Good concept, that''s a postcardy subject all right, but your contrast is pumped WAY high. The water is blinding white, the sky almost twilight-dark, and the whole thing is painful to look at. The water''s so bright you can''t really see anything on it - it washes out the detail, and drags your eye down to something that isn''t interesting to look at, rather than any actual focal point in the picture itself. The border and font label are just right for a postcard, though.', '2003-05-08 15:16:14.000000', NULL, 1),
(292251, 20209, 8488, '<td valign="top">Not a bad try, but I didn''t grade it very highly because there''s no real focal point (attentionwise, not technical-photo-jargon) to the shot. The eye is drawn to a featureless expanse of slightly-rippled river. The mountain''s too small and indistinct to really be the star; the trees are blurry; the sky''s just flat cyan, no interesting clouds to draw the attention. The photo as a whole just doesn''t seem to have much of a point, per se.</td>', 'Not a bad try, but I didn''t grade it very highly because there''s no real focal point (attentionwise, not technical-photo-jargon) to the shot. The eye is drawn to a featureless expanse of slightly-rippled river. The mountain''s too small and indistinct to really be the star; the trees are blurry; the sky''s just flat cyan, no interesting clouds to draw the attention. The photo as a whole just doesn''t seem to have much of a point, per se.', '2003-05-08 15:17:59.000000', NULL, 1),
(292252, 20501, 8488, '<td valign="top">Very pretty sun-stipples, but there''s no point to this photograph, really. The water is the most interesting, and the most central-in-the-composition, thing, but one can only look at it for so long without blinking at the featureless silhouetted shoreline and the blank blue sky and wondering why one bothered to take the picture.<br/> <br/>Gah. That sounds harsher than I meant it to; I''m just trying ot talk through reactions here to give a good idea why I scored it down. It''s a vaguely postcardy kind of scene in general, so points for that, but as an image there really isn''t any purpose, or anything to look at in it.</td>', 'Very pretty sun-stipples, but there''s no point to this photograph, really. The water is the most interesting, and the most central-in-the-composition, thing, but one can only look at it for so long without blinking at the featureless silhouetted shoreline and the blank blue sky and wondering why one bothered to take the picture. Gah. That sounds harsher than I meant it to; I''m just trying ot talk through reactions here to give a good idea why I scored it down. It''s a vaguely postcardy kind of scene in general, so points for that, but as an image there really isn''t any purpose, or anything to look at in it.', '2003-05-08 15:20:39.000000', NULL, 1),
(292254, 20434, 3080, '<td valign="top">When you see postcards, you see "perfect worlds".  I think the sky here is quite bland.  And while it may be true to the scene, I don''t think it is something we would see in a postcard.  Realizing that the weather was not cooperative everywhere, you probably did the best you could, but since the weather wasn''t cooperating, maybe you could have tried something else.  Lighting on the buildings in the distance is really harsh, and I think that is due to the weather conditions as well.  Just not the right time for this shot. ~Heather~</td>', 'When you see postcards, you see "perfect worlds".  I think the sky here is quite bland.  And while it may be true to the scene, I don''t think it is something we would see in a postcard.  Realizing that the weather was not cooperative everywhere, you probably did the best you could, but since the weather wasn''t cooperating, maybe you could have tried something else.  Lighting on the buildings in the distance is really harsh, and I think that is due to the weather conditions as well.  Just not the right time for this shot. ~Heather~', '2003-05-08 15:22:30.000000', NULL, 1),
(292255, 20435, 8488, '<td valign="top">Good choice of subject, but it''s kind of blurry. Most postcards are quite sharp, almost macro-feeling, and in this one even the butterfly''s blurry. The part most in focus, strangely, is the mass of stamens in the flower, which isn''t really what you want the viewer focussing on. The general composition''s quite good, though, and there''s nice contrasts and colors. With a little more care for the focussing this could easily have gotten an 8 or 9 from me.</td>', 'Good choice of subject, but it''s kind of blurry. Most postcards are quite sharp, almost macro-feeling, and in this one even the butterfly''s blurry. The part most in focus, strangely, is the mass of stamens in the flower, which isn''t really what you want the viewer focussing on. The general composition''s quite good, though, and there''s nice contrasts and colors. With a little more care for the focussing this could easily have gotten an 8 or 9 from me.', '2003-05-08 15:22:46.000000', NULL, 1),
(292256, 20543, 8488, '<td valign="top">Almost, but not quite. It''s a decently interesting shot, but the composition is strange and an actual postcard-style angle wouldn''t have had any trees obscuring the main point of interest. As it is, the eye is drawn first to the triangular pediment over the columns and then to the vast expanse of blank beige wall, leaving the viewer kind of foundering there.</td>', 'Almost, but not quite. It''s a decently interesting shot, but the composition is strange and an actual postcard-style angle wouldn''t have had any trees obscuring the main point of interest. As it is, the eye is drawn first to the triangular pediment over the columns and then to the vast expanse of blank beige wall, leaving the viewer kind of foundering there.', '2003-05-08 15:24:00.000000', NULL, 1),
(292258, 20514, 8488, '<td valign="top">Not a bad try, but I had to mark it down a bit. The choice of angle is nicely postcardy, but no postcard would smudge its subject up with that much blur and fog. There''s also really no main ''thing'' to look at - no focal point. One of those tall buildings could have been the star, or the mountains, or the (very pretty!) clouds, but as it is, nothing is but the text, and that''s just an odd choice to have made.</td>', 'Not a bad try, but I had to mark it down a bit. The choice of angle is nicely postcardy, but no postcard would smudge its subject up with that much blur and fog. There''s also really no main ''thing'' to look at - no focal point. One of those tall buildings could have been the star, or the mountains, or the (very pretty!) clouds, but as it is, nothing is but the text, and that''s just an odd choice to have made.', '2003-05-08 15:25:21.000000', NULL, 1),
(292260, 20497, 3080, '<td valign="top">I have to wonder if this is suposed to be Civilization, but seeing it is in Canada, I know you guys spell things funny. *wink*  I like the angle and framing/cropping you chose for this shot.  The sky is beautiful.  very postcard like.  focus and clarity are also good.  I would buy this as a souvenier. ~Heather~</td>', 'I have to wonder if this is suposed to be Civilization, but seeing it is in Canada, I know you guys spell things funny. *wink*  I like the angle and framing/cropping you chose for this shot.  The sky is beautiful.  very postcard like.  focus and clarity are also good.  I would buy this as a souvenier. ~Heather~', '2003-05-08 15:26:21.000000', NULL, 1),
(292262, 20340, 8488, '<td valign="top">Good postcardy choice of subject, good composition (eye is drawn to the bridge, then the sailboats, then the waterskier). I would have graded it 9 or 10 if it didn''t seem quite so ... washed out. The entire left side of the sky is screaming bright featureless white, and the rest of it is a weird cyan sort of shade. A little more saturation, or less overall brightness maybe, would have brought out the colors better.</td>', 'Good postcardy choice of subject, good composition (eye is drawn to the bridge, then the sailboats, then the waterskier). I would have graded it 9 or 10 if it didn''t seem quite so ... washed out. The entire left side of the sky is screaming bright featureless white, and the rest of it is a weird cyan sort of shade. A little more saturation, or less overall brightness maybe, would have brought out the colors better.', '2003-05-08 15:27:16.000000', NULL, 1),
(292267, 20337, 8488, '<td valign="top">Great subject, great composition, great clouds behind (and the one person wandering up the path makes it particularly postcardy). However, the color balance in general is weird. The castle isn''t meant to be that kind of dark bluish purple, is it? I would assume a brighter sort of brownish shade was intended. This was *almost* a 10 for me, but the colors make it look like it was shot with 200-speed Fuji film and not cleaned up afterwards, moving the total feel from ''postcard'' back to ''snapshot.''</td>', 'Great subject, great composition, great clouds behind (and the one person wandering up the path makes it particularly postcardy). However, the color balance in general is weird. The castle isn''t meant to be that kind of dark bluish purple, is it? I would assume a brighter sort of brownish shade was intended. This was *almost* a 10 for me, but the colors make it look like it was shot with 200-speed Fuji film and not cleaned up afterwards, moving the total feel from ''postcard'' back to ''snapshot.''', '2003-05-08 15:28:53.000000', NULL, 1),
(292268, 20532, 3080, '<td valign="top">I sense that you used a wide angle lense to capture this scene.  The distortion of the buildings is such that the buildings look very silly and tilted.  It is a nice scene, however, I think that the distortion ruins it. Focus and clarity are good, and the angle at which you took the image is good, just way too much distortion for my personal tastes.  ~Heather~</td>', 'I sense that you used a wide angle lense to capture this scene.  The distortion of the buildings is such that the buildings look very silly and tilted.  It is a nice scene, however, I think that the distortion ruins it. Focus and clarity are good, and the angle at which you took the image is good, just way too much distortion for my personal tastes.  ~Heather~', '2003-05-08 15:28:56.000000', NULL, 1),
(292275, 20384, 8488, '<td valign="top">Very postcardy, and technically speaking a beautiful shot. The only thing that kept it at 9 and not 10 for me was a lack of a certain spung, that magic ''Wow!'' spark. But I have to save 10s for *something*, right? :-&gt;</td>', 'Very postcardy, and technically speaking a beautiful shot. The only thing that kept it at 9 and not 10 for me was a lack of a certain spung, that magic ''Wow!'' spark. But I have to save 10s for *something*, right? :->', '2003-05-08 15:33:28.000000', NULL, 1),
(292276, 20462, 8488, '<td valign="top">Very postcardy, and technically speaking a beautiful shot. The only thing that kept it at 9 and not 10 for me was a lack of a certain spung, that magic ''Wow!'' spark. But I have to save 10s for *something*, right? :-&gt; Great composition, and nice curvy shapes echoed all over.</td>', 'Very postcardy, and technically speaking a beautiful shot. The only thing that kept it at 9 and not 10 for me was a lack of a certain spung, that magic ''Wow!'' spark. But I have to save 10s for *something*, right? :-> Great composition, and nice curvy shapes echoed all over.', '2003-05-08 15:33:47.000000', NULL, 1),
