(293992, 20385, 5585, '<td valign="top">I would have liked to known where this was....nice pic..</td>', 'I would have liked to known where this was....nice pic..', '2003-05-10 03:24:11.000000', NULL, 1),
(294016, 19947, 7528, '<td valign="top">beautiful</td>', 'beautiful', '2003-05-10 05:46:52.000000', NULL, 1),
(294075, 20437, 7758, '<td valign="top">this is a great shot, composition is strong...it would definately make a great postcard.... if I was to pick anything to look at it would be the small gap in the columns with the blue sky peeping through.... it might have been better to move your position to hide that gap.... it may not have been possible..... overall.... one of my faves this week. Godd luck, Todd.</td>', 'this is a great shot, composition is strong...it would definately make a great postcard.... if I was to pick anything to look at it would be the small gap in the columns with the blue sky peeping through.... it might have been better to move your position to hide that gap.... it may not have been possible..... overall.... one of my faves this week. Godd luck, Todd.', '2003-05-10 09:46:20.000000', NULL, 1),
(294125, 20112, 1717, '<td valign="top">beautiful!  has an old fashioned hand colored look to it.  nice perspective and i really like how the lighthouse is framed by the trees.  good job!</td>', 'beautiful!  has an old fashioned hand colored look to it.  nice perspective and i really like how the lighthouse is framed by the trees.  good job!', '2003-05-10 11:31:12.000000', NULL, 1),
(294127, 20437, 1717, '<td valign="top">oooh...this is lovely!  is this mrs. mag''s photo?  i love the perspective and the cropping.  the font works well, too.  very classy and elegant.  good job!</td>', 'oooh...this is lovely!  is this mrs. mag''s photo?  i love the perspective and the cropping.  the font works well, too.  very classy and elegant.  good job!', '2003-05-10 11:33:24.000000', NULL, 1),
(294129, 19947, 1717, '<td valign="top">beautiful!  the colors are great...not too oversaturated.  my eye is drawn to the boat and it''s a lovely focal point and i love the crop.  well done!</td>', 'beautiful!  the colors are great...not too oversaturated.  my eye is drawn to the boat and it''s a lovely focal point and i love the crop.  well done!', '2003-05-10 11:35:15.000000', NULL, 1),
(294147, 19947, 7628, '<td valign="top">great sky!</td>', 'great sky!', '2003-05-10 12:17:13.000000', NULL, 1),
(294161, 20411, 1280, '<td valign="top">It''s a ;beauty!  Great color saturation and clarity.</td>', 'It''s a ;beauty!  Great color saturation and clarity.', '2003-05-10 12:37:39.000000', NULL, 1),
(294166, 20168, 1280, '<td valign="top">Wonderful abstract.  Very good perspective.</td>', 'Wonderful abstract.  Very good perspective.', '2003-05-10 12:39:34.000000', NULL, 1),
(294171, 20528, 1280, '<td valign="top">Colorful, beautiful clouds/sky and nice composition.</td>', 'Colorful, beautiful clouds/sky and nice composition.', '2003-05-10 12:40:54.000000', NULL, 1),
(294173, 20518, 1280, '<td valign="top">Good picture, not sure it would be a postcard. I like it anyway.</td>', 'Good picture, not sure it would be a postcard. I like it anyway.', '2003-05-10 12:42:41.000000', NULL, 1),
(294177, 20442, 1280, '<td valign="top">I like the scene, but it would be enhanced by showing a person or two enjoying themselves.</td>', 'I like the scene, but it would be enhanced by showing a person or two enjoying themselves.', '2003-05-10 12:50:52.000000', NULL, 1),
(294185, 20446, 1280, '<td valign="top">Other than too much foreground, which centers the horse, this is a lovely scene, and well photographed.</td>', 'Other than too much foreground, which centers the horse, this is a lovely scene, and well photographed.', '2003-05-10 12:59:52.000000', NULL, 1),
(294196, 20207, 1280, '<td valign="top">Beautiful composition with lovely colors.</td>', 'Beautiful composition with lovely colors.', '2003-05-10 13:14:28.000000', NULL, 1),
(294197, 20482, 1280, '<td valign="top">Nice, unique, well executed.</td>', 'Nice, unique, well executed.', '2003-05-10 13:15:30.000000', NULL, 1),
(294198, 20405, 7628, '<td valign="top">This is a lovely picture, and I''d snap it up if I were sending a card!  The only thing: I find the precarious tilt of the house on the right a little disturbing - a result of the wide angle, but could you crop to make it a little less obvious?</td>', 'This is a lovely picture, and I''d snap it up if I were sending a card!  The only thing: I find the precarious tilt of the house on the right a little disturbing - a result of the wide angle, but could you crop to make it a little less obvious?', '2003-05-10 13:17:30.000000', NULL, 1),
(294200, 20536, 1280, '<td valign="top">I like the composition and the sky is very interesting.</td>', 'I like the composition and the sky is very interesting.', '2003-05-10 13:17:51.000000', NULL, 1),
(294201, 20525, 7628, '<td valign="top">Nice idea - look at all those horns!  The composition is a bit random, could be more interesting.</td>', 'Nice idea - look at all those horns!  The composition is a bit random, could be more interesting.', '2003-05-10 13:20:04.000000', NULL, 1),
(294203, 20511, 7628, '<td valign="top">Nice photo, I''m not sure I''d buy it as a card to send or to remind me of a place.</td>', 'Nice photo, I''m not sure I''d buy it as a card to send or to remind me of a place.', '2003-05-10 13:21:11.000000', NULL, 1),
(294205, 20482, 7628, '<td valign="top">A perfect image for texas!  Nicely exectuted,</td>', 'A perfect image for texas!  Nicely exectuted,', '2003-05-10 13:25:00.000000', NULL, 1),
(294206, 20462, 7628, '<td valign="top">Nice composition,  I do wish the Budda''s face were better lit..</td>', 'Nice composition,  I do wish the Budda''s face were better lit..', '2003-05-10 13:27:35.000000', NULL, 1),
(294208, 20161, 1280, '<td valign="top">What a beautiful scene, and well executed.</td>', 'What a beautiful scene, and well executed.', '2003-05-10 13:29:53.000000', NULL, 1),
(294212, 20517, 7628, '<td valign="top">A dramatic composition.  I wish the foliage were fuller, the sky and light more interesting, contrasting.</td>', 'A dramatic composition.  I wish the foliage were fuller, the sky and light more interesting, contrasting.', '2003-05-10 13:38:47.000000', NULL, 1),
(294213, 20478, 7628, '<td valign="top">A wonderful water picture.  The wet rocks, the fall of the water - great!  I think the font and color of the words could match the feeling of the photo better.</td>', 'A wonderful water picture.  The wet rocks, the fall of the water - great!  I think the font and color of the words could match the feeling of the photo better.', '2003-05-10 13:40:56.000000', NULL, 1),
(294218, 20334, 7628, '<td valign="top">Lovely to look at - I really like the colors.  It looks partially submerged in water or ice - what is it?  Inventive but odd.</td>', 'Lovely to look at - I really like the colors.  It looks partially submerged in water or ice - what is it?  Inventive but odd.', '2003-05-10 13:43:58.000000', NULL, 1),
(294222, 20240, 1280, '<td valign="top">Beautiful scene but the whole thing seems to be tilting.   Is it just me? Could be.</td>', 'Beautiful scene but the whole thing seems to be tilting.   Is it just me? Could be.', '2003-05-10 13:46:58.000000', NULL, 1),
(294224, 20519, 7628, '<td valign="top">A lovely poeme.  I like the grassy foreground, and how it contrasts with the dark building (barn?)  Is the house red?  Wish we could see that better, and odd to include the church towerway to left, out of focus and incomplete.</td>', 'A lovely poeme.  I like the grassy foreground, and how it contrasts with the dark building (barn?)  Is the house red?  Wish we could see that better, and odd to include the church towerway to left, out of focus and incomplete.', '2003-05-10 13:47:47.000000', NULL, 1),
(294230, 20111, 1280, '<td valign="top">Excellent picture!  Filled with character and well executed.</td>', 'Excellent picture!  Filled with character and well executed.', '2003-05-10 13:52:24.000000', NULL, 1),
(294232, 20363, 7628, '<td valign="top">Yale?  Nice composition.  The pink of the blossoms looks nice against the gray.  Wish it were even more contrasty, or more interesting light.</td>', 'Yale?  Nice composition.  The pink of the blossoms looks nice against the gray.  Wish it were even more contrasty, or more interesting light.', '2003-05-10 13:56:37.000000', NULL, 1),
(294234, 20523, 1280, '<td valign="top">Beautifully framed.  Good job! The image is a little dark though.</td>', 'Beautifully framed.  Good job! The image is a little dark though.', '2003-05-10 13:57:30.000000', NULL, 1),
(294235, 20332, 7628, '<td valign="top">nice to see something that isn''t a landscape, very exciting subject.  The lines of the stage in the back are distracting - would like to see the fire eaters face</td>', 'nice to see something that isn''t a landscape, very exciting subject.  The lines of the stage in the back are distracting - would like to see the fire eaters face', '2003-05-10 13:58:32.000000', NULL, 1),
(294248, 20454, 7628, '<td valign="top">I like the muted colors, the texture of the land, the peek at the blue-gray coulds mirroring the stream in the foreground.  I dont like the lettering, although the "wish you were here" is funny in the context.</td>', 'I like the muted colors, the texture of the land, the peek at the blue-gray coulds mirroring the stream in the foreground.  I dont like the lettering, although the "wish you were here" is funny in the context.', '2003-05-10 14:14:59.000000', NULL, 1),
(294249, 20424, 7628, '<td valign="top">What a hilarious subject!  I like the black and white of the cows with the yellow dandylions in the front.  I''d like to see more of the cows tho''</td>', 'What a hilarious subject!  I like the black and white of the cows with the yellow dandylions in the front.  I''d like to see more of the cows tho''', '2003-05-10 14:19:36.000000', NULL, 1),
(294250, 20434, 7628, '<td valign="top">Wish we had such colorful houses in New England.  Nice diagonal composition, with the boat in the front.</td>', 'Wish we had such colorful houses in New England.  Nice diagonal composition, with the boat in the front.', '2003-05-10 14:21:03.000000', NULL, 1),
(294252, 20435, 1280, '<td valign="top">Nice!  Great timing!</td>', 'Nice!  Great timing!', '2003-05-10 14:23:16.000000', NULL, 1),
(294253, 20437, 1280, '<td valign="top">Well done.  I like the play of light and shadows.</td>', 'Well done.  I like the play of light and shadows.', '2003-05-10 14:24:10.000000', NULL, 1),
(294254, 20370, 7628, '<td valign="top">You captured the light of dusk very well- the deepenning blue of the sky and the golden glow of the fountain lights work well together.  I would have cropped out the piece of building to the left</td>', 'You captured the light of dusk very well- the deepenning blue of the sky and the golden glow of the fountain lights work well together.  I would have cropped out the piece of building to the left', '2003-05-10 14:24:25.000000', NULL, 1),
(294256, 20442, 7628, '<td valign="top">perfect NE seashore!  Like the layers of waves - the town in the distance</td>', 'perfect NE seashore!  Like the layers of waves - the town in the distance', '2003-05-10 14:25:51.000000', NULL, 1),
(294257, 20448, 7628, '<td valign="top">There''s a geysir near Perlan? Cool shot.  Great blues and greens, nice composition!  to be picky -Crop out the tree on the right.</td>', 'There''s a geysir near Perlan? Cool shot.  Great blues and greens, nice composition!  to be picky -Crop out the tree on the right.', '2003-05-10 14:27:35.000000', NULL, 1),
(294261, 20168, 7628, '<td valign="top">cool absract composition!  I''d snap up this card right away!  Wish the lettering were as great as the photo!</td>', 'cool absract composition!  I''d snap up this card right away!  Wish the lettering were as great as the photo!', '2003-05-10 14:32:43.000000', NULL, 1),
(294287, 20154, 714, '<td valign="top">The colors are outstanding!  How did you get everything so dark?</td>', 'The colors are outstanding!  How did you get everything so dark?', '2003-05-10 14:56:01.000000', NULL, 1),
(294373, 20254, 3080, '<td valign="top">Nice shot.  Really pretty scene, good for a postcard.  About half way up the large mountain to the right is a blue dot that I find myself staring at for along time trying to figure out what it is.  I guess that would be a distraction then.  Otherwise, lighting conditions look ok for the shot, and the focus and clarity are good.  Angle and framing/cropping are also nice.  ~Heather~</td>', 'Nice shot.  Really pretty scene, good for a postcard.  About half way up the large mountain to the right is a blue dot that I find myself staring at for along time trying to figure out what it is.  I guess that would be a distraction then.  Otherwise, lighting conditions look ok for the shot, and the focus and clarity are good.  Angle and framing/cropping are also nice.  ~Heather~', '2003-05-10 16:35:58.000000', NULL, 1),
(294376, 20515, 3080, '<td valign="top">Wide angle lens distortion?  The trees on the right tilt left, and the trees on the left tilt right.  Everything tilts inward.  Usually a side effect of a wide angle lens.  The scene is pretty, I think it''s be better with some less naked trees, but still not bad.  I like how the little hill kind of frames the photo. ~Heather~</td>', 'Wide angle lens distortion?  The trees on the right tilt left, and the trees on the left tilt right.  Everything tilts inward.  Usually a side effect of a wide angle lens.  The scene is pretty, I think it''s be better with some less naked trees, but still not bad.  I like how the little hill kind of frames the photo. ~Heather~', '2003-05-10 16:39:05.000000', NULL, 1),
(294381, 20280, 3080, '<td valign="top">Absolutely stunning view.  Perfect postcard.  If I HAD to make a suggestion, I''d suggest to try toning the clouds down slightly, as they might be just a bit bright, otherwise, excellent shot.  The angle and framing/cropping is good, as is the focus and clarity.  Great find. ~Heather~</td>', 'Absolutely stunning view.  Perfect postcard.  If I HAD to make a suggestion, I''d suggest to try toning the clouds down slightly, as they might be just a bit bright, otherwise, excellent shot.  The angle and framing/cropping is good, as is the focus and clarity.  Great find. ~Heather~', '2003-05-10 16:56:46.000000', NULL, 1),
(294382, 20405, 3080, '<td valign="top">Excellent color.  Focus and clarity are great as well.  Looks like the buildings are leaning inward.  Was there some wide angle lens distortion?  Still quite good, actually, I like it, as it really draws us up to the nice sky and color in the sky/rooftops and tree.  Good for a postcard. ~Heather~</td>', 'Excellent color.  Focus and clarity are great as well.  Looks like the buildings are leaning inward.  Was there some wide angle lens distortion?  Still quite good, actually, I like it, as it really draws us up to the nice sky and color in the sky/rooftops and tree.  Good for a postcard. ~Heather~', '2003-05-10 17:01:07.000000', NULL, 1),
(294427, 20462, 1280, '<td valign="top">Good job capturing the highlights and shadows.  Good representation.</td>', 'Good job capturing the highlights and shadows.  Good representation.', '2003-05-10 19:56:39.000000', NULL, 1),
(294460, 20317, 5792, '<td valign="top">Nice small town view</td>', 'Nice small town view', '2003-05-10 21:05:23.000000', NULL, 1),
(294461, 20138, 5792, '<td valign="top">I spent some fun times there</td>', 'I spent some fun times there', '2003-05-10 21:06:30.000000', NULL, 1),
(294463, 20383, 5792, '<td valign="top">Tranquil reflection in the canal. Excellant.</td>', 'Tranquil reflection in the canal. Excellant.', '2003-05-10 21:07:39.000000', NULL, 1),
(294466, 20523, 5792, '<td valign="top">Effective use building shadow for framing</td>', 'Effective use building shadow for framing', '2003-05-10 21:09:11.000000', NULL, 1),
(294468, 20335, 5792, '<td valign="top">Good sunset view and patio silhouette. Nice getting the shot blocking the sun with a branch. I''ve hiked the Olympic National Park beach section between towns and it is beautiful territory.</td>', 'Good sunset view and patio silhouette. Nice getting the shot blocking the sun with a branch. I''ve hiked the Olympic National Park beach section between towns and it is beautiful territory.', '2003-05-10 21:13:37.000000', NULL, 1),
(294469, 20207, 5792, '<td valign="top">Great image clarity</td>', 'Great image clarity', '2003-05-10 21:14:32.000000', NULL, 1),
(294471, 20497, 5792, '<td valign="top">Nice composition and framing. Good architecture shot as well.</td>', 'Nice composition and framing. Good architecture shot as well.', '2003-05-10 21:21:00.000000', NULL, 1),
(294483, 20417, 5792, '<td valign="top">Great color, clarity and framing</td>', 'Great color, clarity and framing', '2003-05-10 21:29:50.000000', NULL, 1),
(294511, 20514, 4793, '<td valign="top">This would be a nice postcard</td>', 'This would be a nice postcard', '2003-05-10 22:57:12.000000', NULL, 1),
