(294515, 20478, 4793, '<td valign="top">Very nice, focus and comp. great</td>', 'Very nice, focus and comp. great', '2003-05-10 23:01:18.000000', NULL, 1),
(294516, 20497, 4793, '<td valign="top">Very nice shot of a beautiful building.</td>', 'Very nice shot of a beautiful building.', '2003-05-10 23:04:03.000000', NULL, 1),
(294518, 20528, 4793, '<td valign="top">Great postcard</td>', 'Great postcard', '2003-05-10 23:06:07.000000', NULL, 1),
(294520, 20207, 4793, '<td valign="top">A stunning shot, I love it. I see nothing wrong with this one, would make a great wall poster. O Canada, I love the beautiful and diverse landscapes in all of her provinces. Keep up the good work.10</td>', 'A stunning shot, I love it. I see nothing wrong with this one, would make a great wall poster. O Canada, I love the beautiful and diverse landscapes in all of her provinces. Keep up the good work.10', '2003-05-10 23:17:08.000000', NULL, 1),
(294522, 20414, 4793, '<td valign="top">Very nice shot</td>', 'Very nice shot', '2003-05-10 23:20:27.000000', NULL, 1),
