(294539, 20336, 4793, '<td valign="top">Very nice</td>', 'Very nice', '2003-05-10 23:32:28.000000', NULL, 1),
(294542, 20446, 7890, '<td valign="top">lovely picture, and composition, might of cropped alittle on the bottom, but I love the barn and horse, and little pink flowers. good work.</td>', 'lovely picture, and composition, might of cropped alittle on the bottom, but I love the barn and horse, and little pink flowers. good work.', '2003-05-10 23:40:07.000000', NULL, 1),
