(294549, 20432, 8633, '<td valign="top">Beautiful picture.<br/>This post card definitely makes me want to go there.</td>', 'Beautiful picture.This post card definitely makes me want to go there.', '2003-05-10 23:56:41.000000', NULL, 1),
(294551, 20274, 8633, '<td valign="top">This has a nice ''old time'' postcard feel.</td>', 'This has a nice ''old time'' postcard feel.', '2003-05-10 23:58:18.000000', NULL, 1),
(294554, 20253, 8633, '<td valign="top">Great picture.<br/>I love the sepia tones.</td>', 'Great picture.I love the sepia tones.', '2003-05-11 00:04:01.000000', NULL, 1),
(294574, 20515, 6870, '<td valign="top">The lines here really draw the eye around the photo. To me, this image doesn''t look "pretty" enough for me to want to go there, and it doesn''t quite look sarcastic enough to see this as a joke. Hmmm. I''ll consider myself stupid and give you a decent score!</td>', 'The lines here really draw the eye around the photo. To me, this image doesn''t look "pretty" enough for me to want to go there, and it doesn''t quite look sarcastic enough to see this as a joke. Hmmm. I''ll consider myself stupid and give you a decent score!', '2003-05-11 01:17:13.000000', NULL, 1),
(294575, 20535, 6870, '<td valign="top">I love the text-as-flag. The images seems slightly grainy, and I can''t really determine a purpose to it. Lovely composition. Nice sky capture, too.</td>', 'I love the text-as-flag. The images seems slightly grainy, and I can''t really determine a purpose to it. Lovely composition. Nice sky capture, too.', '2003-05-11 01:18:29.000000', NULL, 1),
(294576, 20396, 6870, '<td valign="top">Lines and contrasts really make the eye move through and then around the photo! Light seems a bit harsh and "ordinary,", but composition is wonderful.</td>', 'Lines and contrasts really make the eye move through and then around the photo! Light seems a bit harsh and "ordinary,", but composition is wonderful.', '2003-05-11 01:20:11.000000', NULL, 1),
(294577, 20268, 8634, '<td valign="top">Now THIS one, I like!</td>', 'Now THIS one, I like!', '2003-05-11 01:20:13.000000', NULL, 1),
