(294661, 20497, 8507, '<td valign="top">Geat lines!</td>', 'Geat lines!', '2003-05-11 09:36:52.000000', NULL, 1),
(294684, 20213, 1031, '<td valign="top">The shot is fine, lighting and color a little flat (a problem I have frequently!). Aspect ratio is uncommon for a standard postcard, and I think I''d use a different color for the border.</td>', 'The shot is fine, lighting and color a little flat (a problem I have frequently!). Aspect ratio is uncommon for a standard postcard, and I think I''d use a different color for the border.', '2003-05-11 11:43:49.000000', NULL, 1),
(294686, 20481, 1031, '<td valign="top">I think I''d want to be wearing a parachute...</td>', 'I think I''d want to be wearing a parachute...', '2003-05-11 11:45:11.000000', NULL, 1),
(294690, 20268, 5792, '<td valign="top">Nice use of ROT, good color combination</td>', 'Nice use of ROT, good color combination', '2003-05-11 11:50:18.000000', NULL, 1),
(294691, 20269, 1031, '<td valign="top">"Bless it''s pointy little head." Type and border give the whole thing the look/feel of an illustration; works well with this image.</td>', '"Bless it''s pointy little head." Type and border give the whole thing the look/feel of an illustration; works well with this image.', '2003-05-11 11:50:53.000000', NULL, 1),
(294693, 20268, 1031, '<td valign="top">I think I''d rather see the orange groves, if there are any left...does look tasty though.</td>', 'I think I''d rather see the orange groves, if there are any left...does look tasty though.', '2003-05-11 11:52:52.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(294694, 20382, 1031, '<td valign="top">I''d have made the type much heavier -- with the large dark areas formed by the cave openings and the tree trunk the type could be about twice as thick and more readable. And/or use a drop-shadow or similar.<br/>Another way to deal with a busy background (not usable this challenge) is to create a feathered selection where the type will be and fade back that part of the photo.</td>', 'I''d have made the type much heavier -- with the large dark areas formed by the cave openings and the tree trunk the type could be about twice as thick and more readable. And/or use a drop-shadow or similar.Another way to deal with a busy background (not usable this challenge) is to create a feathered selection where the type will be and fade back that part of the photo.', '2003-05-11 11:56:29.000000', NULL, 1),
(294695, 20504, 1031, '<td valign="top">Not one''s stereotypical view of that city!</td>', 'Not one''s stereotypical view of that city!', '2003-05-11 11:57:41.000000', NULL, 1),
(294697, 20340, 1031, '<td valign="top">Not a standard aspect ratio of cards. I''d have either put all the type in the center or on the two edges, but not mixed like this. Stacking the type in the center would give you a good excuse to increase the lower border and balance the size.</td>', 'Not a standard aspect ratio of cards. I''d have either put all the type in the center or on the two edges, but not mixed like this. Stacking the type in the center would give you a good excuse to increase the lower border and balance the size.', '2003-05-11 12:04:19.000000', NULL, 1),
(294698, 20516, 1031, '<td valign="top">This angle gives a good idea of the whole building. If you right-adjust the type, the left margin will follow the roofline, especially if you reduce the size of the last line slightly.</td>', 'This angle gives a good idea of the whole building. If you right-adjust the type, the left margin will follow the roofline, especially if you reduce the size of the last line slightly.', '2003-05-11 12:06:24.000000', NULL, 1),
(294699, 20337, 1031, '<td valign="top">I''d prefer the type just a little smaller/farther from the top of the tower.</td>', 'I''d prefer the type just a little smaller/farther from the top of the tower.', '2003-05-11 12:08:13.000000', NULL, 1),
(294701, 20356, 1031, '<td valign="top">An interesting example of how the "subject" needn''t be in focus to be effective!</td>', 'An interesting example of how the "subject" needn''t be in focus to be effective!', '2003-05-11 12:10:45.000000', NULL, 1),
(294703, 20523, 1031, '<td valign="top">Great job framing your subject -- I like doing that too.</td>', 'Great job framing your subject -- I like doing that too.', '2003-05-11 12:13:39.000000', NULL, 1),
(294707, 20448, 1031, '<td valign="top">Kinda makes it look like another planet altogether...</td>', 'Kinda makes it look like another planet altogether...', '2003-05-11 12:24:48.000000', NULL, 1),
(294708, 20454, 1031, '<td valign="top">I think I''d have stuck the upper type in the sky area, and a bit smaller.</td>', 'I think I''d have stuck the upper type in the sky area, and a bit smaller.', '2003-05-11 12:26:01.000000', NULL, 1),
(294712, 20528, 1031, '<td valign="top">Looks windy, probably a good thing...</td>', 'Looks windy, probably a good thing...', '2003-05-11 12:28:11.000000', NULL, 1),
(294713, 20456, 1031, '<td valign="top">A good postcard shot. One typo: since it''s the building itself, it''s spelled Capitol, even though Austin is the Capital of Texas. Ain''t English wunnerful?</td>', 'A good postcard shot. One typo: since it''s the building itself, it''s spelled Capitol, even though Austin is the Capital of Texas. Ain''t English wunnerful?', '2003-05-11 12:31:23.000000', NULL, 1),
(294716, 19823, 1031, '<td valign="top">Getting microwaved from the looks of things...the same shot without the vehicles could be a big seller there...</td>', 'Getting microwaved from the looks of things...the same shot without the vehicles could be a big seller there...', '2003-05-11 12:38:19.000000', NULL, 1),
(294718, 20384, 1031, '<td valign="top">My taste would be to heighten the contrast a bit, but this somewhat hazy look may be a more accurate representation of the area. Makes me want to see it myself, which is the point I guess...</td>', 'My taste would be to heighten the contrast a bit, but this somewhat hazy look may be a more accurate representation of the area. Makes me want to see it myself, which is the point I guess...', '2003-05-11 12:42:30.000000', NULL, 1),
(294723, 20424, 2011, '<td valign="top">Where is this?  This is AWESOME!  I would love to visit</td>', 'Where is this?  This is AWESOME!  I would love to visit', '2003-05-11 12:59:57.000000', NULL, 1),
(294766, 20482, 8637, '<td valign="top">Great concept with almost perfect tonal quality...especially like the bronze tips on the spurs...blend well with the Texas text.  thanks</td>', 'Great concept with almost perfect tonal quality...especially like the bronze tips on the spurs...blend well with the Texas text.  thanks', '2003-05-11 14:31:33.000000', NULL, 1),
(294776, 20478, 1031, '<td valign="top">Clever idea with the type, but I don''t think it quite works. I''d just right-adjust all three words and move them a little to the right from where wou have them.</td>', 'Clever idea with the type, but I don''t think it quite works. I''d just right-adjust all three words and move them a little to the right from where wou have them.', '2003-05-11 15:10:24.000000', NULL, 1),
(294777, 20270, 1031, '<td valign="top">Haven''t seen one of those in a while. I''d rather have the type reversed or drop-shadowed for added readability.</td>', 'Haven''t seen one of those in a while. I''d rather have the type reversed or drop-shadowed for added readability.', '2003-05-11 15:12:14.000000', NULL, 1),
(294778, 20511, 1031, '<td valign="top">I''d trim some of the sky to make the shape more postcard-like.</td>', 'I''d trim some of the sky to make the shape more postcard-like.', '2003-05-11 15:13:34.000000', NULL, 1),
(294785, 20424, 8609, '<td valign="top">Very whimsical....I like it!</td>', 'Very whimsical....I like it!', '2003-05-11 15:23:03.000000', NULL, 1),
(294795, 20375, 1031, '<td valign="top">I like the lighting and the lettering, but it''s too square to be a "typical" postcard.</td>', 'I like the lighting and the lettering, but it''s too square to be a "typical" postcard.', '2003-05-11 15:34:12.000000', NULL, 1),
(294796, 20414, 1031, '<td valign="top">I think you could crop the right a little to take out the pole and not lose too much of the falls.</td>', 'I think you could crop the right a little to take out the pole and not lose too much of the falls.', '2003-05-11 15:35:01.000000', NULL, 1),
(294797, 20154, 6912, '<td valign="top">this shot makes me want to go to see this place! Very postcardic! Wonderful light, great that the duck got in the pic too! 10 from me! Anastasia<br/><br/><i>Message edited by author 2003-05-12 03:21:33.</i></td>', 'this shot makes me want to go to see this place! Very postcardic! Wonderful light, great that the duck got in the pic too! 10 from me! Anastasia', '2003-05-11 15:38:46.000000', '2003-05-12 04:21:33.000000', 1),
(294801, 20449, 1031, '<td valign="top">I''d put that type in the lower-left. Actually, since this is a little too tall for a standard postcard anyway, you could leave the type but crop some from the bottom.</td>', 'I''d put that type in the lower-left. Actually, since this is a little too tall for a standard postcard anyway, you could leave the type but crop some from the bottom.', '2003-05-11 15:41:33.000000', NULL, 1),
(294811, 20334, 1031, '<td valign="top">Maybe the best color of the recent poppy photos...looks postcard-like for sure.</td>', 'Maybe the best color of the recent poppy photos...looks postcard-like for sure.', '2003-05-11 15:59:38.000000', NULL, 1),
(294812, 20168, 1031, '<td valign="top">A different perspective on this landmark. I''d move the type down, crop the top a tiny bit to a standard aspect ratio.</td>', 'A different perspective on this landmark. I''d move the type down, crop the top a tiny bit to a standard aspect ratio.', '2003-05-11 16:01:46.000000', NULL, 1),
(294821, 20336, 1031, '<td valign="top">A fine shot, needs a little cropped top and bottom to fit standard size. Good job bringing out the color from what looks like a flat lighting situation.</td>', 'A fine shot, needs a little cropped top and bottom to fit standard size. Good job bringing out the color from what looks like a flat lighting situation.', '2003-05-11 16:12:56.000000', NULL, 1),
(294828, 20268, 1280, '<td valign="top">I love this simple and beautiful composition.  The colors are so sweet and pure.  I don''t care for the border.  The color doesn''t complement the subject,  but that  doesn''t effect my scoring. :-)</td>', 'I love this simple and beautiful composition.  The colors are so sweet and pure.  I don''t care for the border.  The color doesn''t complement the subject,  but that  doesn''t effect my scoring. :-)', '2003-05-11 16:21:58.000000', NULL, 1),
(294830, 20422, 1280, '<td valign="top">Nice colorful image.  The text is out of context though.  If this was a post card for "save the world"  a child or wildlife might be  more appropriate.</td>', 'Nice colorful image.  The text is out of context though.  If this was a post card for "save the world"  a child or wildlife might be  more appropriate.', '2003-05-11 16:24:10.000000', NULL, 1),
(294831, 20540, 1280, '<td valign="top">If cropped differently the upper floor wouldn''t show, which is too bright and draws attention from the street level.</td>', 'If cropped differently the upper floor wouldn''t show, which is too bright and draws attention from the street level.', '2003-05-11 16:31:15.000000', NULL, 1),
(294832, 20516, 1280, '<td valign="top">Ahhhhh....I''ve been there...had a great time.  Nice architectural shot.  If you''d have backed up or zoomed out you could have included the peak.</td>', 'Ahhhhh....I''ve been there...had a great time.  Nice architectural shot.  If you''d have backed up or zoomed out you could have included the peak.', '2003-05-11 16:33:02.000000', NULL, 1),
(294833, 20383, 1280, '<td valign="top">Very lovely, clear image.  Would have been better to have more of, or none of the boat.</td>', 'Very lovely, clear image.  Would have been better to have more of, or none of the boat.', '2003-05-11 16:36:21.000000', NULL, 1),
(294834, 20253, 1280, '<td valign="top">Very nicely done.  Beautiful job!</td>', 'Very nicely done.  Beautiful job!', '2003-05-11 16:37:27.000000', NULL, 1),
(294839, 20515, 1280, '<td valign="top">Nice....and I LOVE NY!!!   Well composed and good color and texture.</td>', 'Nice....and I LOVE NY!!!   Well composed and good color and texture.', '2003-05-11 16:44:06.000000', NULL, 1),
(294841, 20269, 4411, '<td valign="top">This looks so professional. Great shot and an excellent job with the text. How did I ever give this a 9? Bumping into my 10''s : )</td>', 'This looks so professional. Great shot and an excellent job with the text. How did I ever give this a 9? Bumping into my 10''s : )', '2003-05-11 16:45:55.000000', NULL, 1),
