(500804, 20411, 5728, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by pitsaman:</b></div><hr/><i>Hoe you like E20 ?Do you still have it?</i></td></tr></table> <br/> <br/>I had an E20 for about 2 months between my C-5050 and my 10D. I didn''t really like it which is why I exchanged it for the 10D.</td>', 'Originally posted by pitsaman:Hoe you like E20 ?Do you still have it?  I had an E20 for about 2 months between my C-5050 and my 10D. I didn''t really like it which is why I exchanged it for the 10D.', '2003-12-02 02:48:05.000000', NULL, 0),
(761818, 20207, 22734, '<td valign="top">Very ompressive. Good port.</td>', 'Very ompressive. Good port.', '2004-06-13 22:17:57.000000', NULL, 0),
